/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A60 staging · exact frozen manifest laryngeal–learned (80 lemmas). */
'use strict';
const D=globalThis.RA.D;
const Q=(w,n,s,p,a,b,c,x)=>({id:w+'.q'+n,senseId:w+'.s'+s,errorType:'meaning',type:'辨义与用法',prompt:p,options:[a,b,c],answer:a,explain:x});
const M=(wrong,right,reason,type='meaning')=>({errorType:type,wrong,right,reason});
const C=(s,domain,en,zh,structure,grammar,rationale)=>({senseId:s,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:[c],mistakes:[m],quiz:qs});

P('laryngeal','Laryngeal is the medical adjective formed from larynx; Greek larynx passed through medical Latin and French, while the deeper origin is uncertain.',C('laryngeal.s1','耳鼻喉科','The singer rested her voice after doctors diagnosed a laryngeal infection.','医生诊断这名歌手患有喉部感染后，她让嗓子休息了。','The singer rested her voice / after doctors diagnosed / a laryngeal infection.','laryngeal 修饰 infection，表示感染位于喉部；after 引出休息的原因。','诊断对象是喉部感染，符合医学形容词义。'),M('The report called the illness laryngeal although it affected only the ankle and had no connection to the voice box.','The report called the illness an ankle infection because it affected the ankle, not the larynx.','只影响踝部的病症不是 laryngeal。'),[Q('laryngeal',1,1,'A laryngeal condition affects the?','larynx or voice box','outer surface of the ankle','space between two planets','laryngeal 指与喉有关。'),Q('laryngeal',2,1,'Why did the singer rest her voice?','doctors diagnosed an infection in the larynx','the infection was only in her ankle','she had no voice or throat problem','语境说明她患喉部感染。'),Q('laryngeal',3,1,'Which phrase is correctly formed?','laryngeal examination','laryngeal of the voice box','laryngeal infection in the ankle','laryngeal 是形容词，可修饰 examination。'),Q('laryngeal',4,1,'The noun that laryngeal relates to is?','larynx','latex','lateral','laryngeal 由 larynx 派生。')]);
P('larynx','Larynx entered English through French and medical Latin from Greek larynx; the Greek word’s deeper origin is uncertain.',C('larynx.s1','发声机制','During the examination, the doctor used a small camera to inspect the larynx and the vocal folds inside it.','检查时，医生用小型摄像设备查看喉部及其中的声带。','During the examination / the doctor used a small camera / to inspect the larynx / and the vocal folds inside it.','larynx 是 inspect 的宾语；inside it 指喉部内部。','喉部容纳声带并保护气道，符合 s1。'),M('The larynx is the bony joint in the wrist that bends the hand.','The wrist joint bends the hand; the larynx is the voice box in the neck.','喉部在颈部，不是腕关节。'),[Q('larynx',1,1,'The larynx is the structure that contains the?','vocal folds in the neck','bones that bend the wrist','leaves of a plant','larynx 是包含声带的喉部结构。'),Q('larynx',2,1,'What did the doctor inspect with a camera?','the larynx and its vocal folds','the wrist joint and its bones','the outer surface of a leaf','检查对象是喉部及声带。'),Q('larynx',3,1,'Which everyday term can refer to the larynx?','voice box','last name','lateen sail','voice box 是 larynx 的俗称。'),Q('larynx',4,1,'The larynx also helps protect the?','airway','eye lashes','equator','喉部结构也帮助保护气道。')]);
P('laser','Laser is an acronym for “light amplification by stimulated emission of radiation,” coined for the device and the beam it produces.',C('laser.s2','皮肤治疗','The dermatologist used a laser to remove the mark, adjusting the machine so the beam reached only the targeted area.','皮肤科医生用激光去除这处印记，并调整设备使光束只照到目标区域。','The dermatologist used a laser / to remove the mark / adjusting the machine / so the beam reached only the targeted area.','laser 在此指产生激光束的设备；to remove 说明用途。','医生操作设备以产生光束进行治疗，符合 s2。'),M('The technician called the lamp a laser although it emitted only a broad, weak mixture of ordinary light.','The technician called it a regular lamp because it did not produce a narrow amplified beam.','普通宽光谱灯不具备 laser 光束特征。'),[Q('laser',1,1,'A laser produces a beam of light that is typically?','narrow and intense','broad and weak like ordinary room light','made of sound waves','激光通常是窄而强的光束。'),Q('laser',2,2,'In the treatment, the word laser refers to?','the machine used to direct the beam','the patient’s family name','a medical room with no light source','此处 laser 是发射光束的设备。'),Q('laser',3,1,'What does the acronym laser expand to?','light amplification by stimulated emission of radiation','late arrival by sudden evening rain','lateral adjustment of signal energy','laser 是该英文技术短语的首字母缩略词。'),Q('laser',4,1,'Which phrase is natural?','a laser beam','a laser of the equator','a larynx beam of sound','laser beam 是常见搭配。')]);
P('lash','Lash as “strike” is recorded in Middle English and may be imitative; the nautical verb “tie with rope” is separately traced to French lachier.',C('lash.s4','甲板装载','Before the storm, the crew lashed the spare containers to the deck with thick ropes.','暴风雨来临前，船员用粗绳把备用集装箱牢牢捆在甲板上。','Before the storm / the crew lashed the spare containers / to the deck / with thick ropes.','lashed 是及物动词，表示用绳捆牢；to the deck 指固定位置。','货物由绳索固定，符合 s4，不是“鞭打”之义。'),M('The crew lashed the containers to the deck by leaving them loose and unfastened on the rolling ship.','The crew secured the containers to the deck with ropes.','放任货物松动并未捆牢，与 lash down 的固定义相反。'),[Q('lash',1,4,'To lash cargo to a deck is to?','tie it firmly with rope','hit it repeatedly with a whip','praise it in a formal speech','lash 可表示用绳捆牢。'),Q('lash',2,3,'Which sense appears in “rain lashed the windows”?','strike with force','tie with rope','eyelid hair','雨猛烈拍打窗户，属于动词 s3。'),Q('lash',3,2,'A lash of a whip can mean?','a blow or the flexible part of the whip','a young woman','a name shared by family members','名词 lash 可指鞭打或鞭梢。'),Q('lash',4,5,'Which sentence uses lash for speech?','The editorial lashed out at the proposal.','The editorial lashed the cargo to the deck.','The editorial had long lashes.','lash out at 可指严厉抨击。')]);
P('lass','Lass is a regional English and Scots word for a girl or young woman; its older source is uncertain, with proposed Scandinavian connections.',C('lass.s1','苏格兰乡村','A lass from the village volunteered to guide the visitors along the footpath to the old mill.','村里一位年轻姑娘主动带游客沿小径前往旧磨坊。','A lass from the village / volunteered to guide the visitors / along the footpath / to the old mill.','lass 作主语名词，指年轻女性；to guide 引出她自愿提供的帮助。','语境中的成年年轻女性符合 s1。'),M('The guide was called a lass although he was an old stone bridge with no person there.','The guide was a young woman from the village.','石桥不是女孩或年轻女性。'),[Q('lass',1,1,'A lass is?','a girl or young woman','a machine for shaping wood','a legal claim filed in court','lass 是女孩或年轻女子。'),Q('lass',2,1,'Who guided the visitors to the mill?','a young woman from the village','a machine operator with no guide','a group of visiting lawyers','句中 lass 是主动带路的村庄姑娘。'),Q('lass',3,1,'Which phrase is natural in Scots or regional English?','the lass by the gate','the laryngeal lass of the courthouse','the lass is a narrow light beam','lass 是地域性口语名词。'),Q('lass',4,1,'The history of lass is best described as?','uncertain, with proposed Scandinavian links','a proven acronym for a light beam','a Latin term meaning “side”','该词源存在多种说法，不能武断确定。')]);
P('lassie','Lassie is a Scottish diminutive of lass, formed with -ie, and means a young girl or young woman.',C('lassie.s1','牧场生活','The lassie carried a pail of water to the sheep pens before the afternoon heat set in.','午后天气变热前，这名小姑娘把一桶水提到羊圈。','The lassie carried a pail of water / to the sheep pens / before the afternoon heat / set in.','lassie 作主语名词；before 从句说明她送水的时间。','苏格兰及方言语境中的年轻女孩，符合 s1。'),M('The lassie was the elderly farmer’s tractor, which carried water by itself.','The lassie was a young girl who carried the water.','拖拉机不是女孩；lassie 指年轻女性。'),[Q('lassie',1,1,'A lassie is usually?','a young girl or young woman','a water-carrying machine','a court case','lassie 指小姑娘或年轻女子。'),Q('lassie',2,1,'What did the lassie carry?','a pail of water to the sheep pens','a laser beam to the courtroom','a surname to the mill','句中小姑娘给羊圈送水。'),Q('lassie',3,1,'Lassie is especially associated with?','Scottish or regional usage','formal medical anatomy only','a legal term for a claim','lassie 带有苏格兰或方言色彩。'),Q('lassie',4,1,'How is lassie formed?','lass with the diminutive ending -ie','late with the superlative ending -est','Latin with the acronym laser','lassie 是 lass 加苏格兰小称后缀 -ie。')]);
P('last','The adjective last comes from Old English latost, “slowest, latest,” the superlative related to late; it now commonly means final in a sequence.',C('last.s1','图书出版','The final chapter was the last part of the novel, bringing the two story lines together.','最后一章是这部小说的末尾部分，将两条故事线汇合起来。','The final chapter / was the last part / of the novel / bringing the two story lines together.','last 作定语修饰 part，表示序列中最后的部分；bringing 补充该章的作用。','该章节位于作品末尾，符合 s1。'),M('The last chapter came first, before every other chapter, and no chapter followed it.','The first chapter came before every other chapter.','位于所有章节之前的是 first，不是 last。'),[Q('last',1,1,'The last item in a sequence comes?','after all the others','before every other item','only recently before now','last 的序列义是排在所有其他项之后。'),Q('last',2,2,'In “I saw her last night,” last means?','most recent, just before now','the final person in a list','to continue for two hours','last night 表示最近过去的一个晚上。'),Q('last',3,3,'If a meeting lasted two hours, last is a?','verb meaning continue for a period','noun meaning a family surname','superlative adjective meaning most recent','last 作动词可表示持续。'),Q('last',4,4,'In “At last the bus came,” last is used as?','a noun in the phrase meaning finally','an adjective before a family name','a verb meaning praised','at last 意为终于。')]);
P('last name','Last name is a compound of last and name, used for the family name shared with relatives in many naming systems.',C('last name.s1','填写表格','The application asks each visitor to enter a last name so staff can sort the check-in list alphabetically.','申请表要求每位访客填写姓氏，方便工作人员按字母顺序整理登记名单。','The application asks each visitor / to enter a last name / so staff can sort / the check-in list alphabetically.','last name 作 enter 的宾语，指姓；so 引出填写姓氏的目的。','共享家族名用于识别和排序，符合 s1。'),M('She entered her last name in the given-name box even though the form clearly asked for her family name.','She entered her family name in the last-name box.','把姓填入名的栏目混淆了 last name 与 given name。'),[Q('last name',1,1,'A last name is usually a person’s?','family name shared with relatives','first personal name given at birth only','nickname for a pet','last name 指姓氏。'),Q('last name',2,1,'Why did the form request a last name?','to sort the check-in list by family name','to record the visitor’s shoe size','to identify the last bus of the day','表格收集姓氏以便按字母整理。'),Q('last name',3,1,'Which instruction is clear?','Write your last name in this box.','Write your last name where the form asks for your shoe size.','Write your last name between two planets.','last name 可用作表格指示中的名词短语。'),Q('last name',4,1,'In many English forms, last name is also called a?','surname or family name','larynx','latitude','surname 是 last name 的近义词。')]);
P('lasting','Lasting is formed from the verb last plus -ing and describes something that continues for a long time.',C('lasting.s1','社区项目','The neighborhood garden had a lasting effect: even after the grant ended, residents kept meeting to maintain it.','社区花园产生了持久影响：即使资助结束，居民仍继续聚会维护花园。','The neighborhood garden / had a lasting effect / even after the grant ended / residents kept meeting to maintain it.','lasting 修饰 effect，表示影响持续很久；even after 强调资助结束后影响仍在。','居民持续维护说明项目影响没有很快消失，符合 s1。'),M('The project had a lasting effect that disappeared immediately the next morning and was never noticed again.','The project had only a brief effect because it vanished the next morning.','立刻消失的影响不叫 lasting。'),[Q('lasting',1,1,'A lasting effect continues?','for a long time','for only an instant','only between two states','lasting 表示持久的。'),Q('lasting',2,1,'What showed that the garden’s effect was lasting?','residents maintained it after the grant ended','everyone forgot it the same day','the garden closed before opening','资助结束后居民仍维护，表明影响持久。'),Q('lasting',3,1,'Which phrase is natural?','a lasting friendship','a lasting moment that ended instantly','a lasting to the committee','lasting 可修饰 friendship。'),Q('lasting',4,1,'The verb related to lasting is?','last, meaning continue','lash, meaning tie with rope','laud, meaning praise','lasting 源自表示持续的动词 last。')]);
P('lastly','Lastly is formed from last plus -ly and marks the final point in an ordered list or sequence.',C('lastly.s1','会议发言','Lastly, the chair thanked the volunteers and closed the meeting.','最后，主席感谢了志愿者并宣布散会。','Lastly / the chair thanked the volunteers / and closed / the meeting.','句首 lastly 作为篇章连接副词，提示这是列举的最后一点。','它引出发言清单中的最后一项，符合 s1。'),M('The speaker said “lastly” and then introduced five earlier points that were supposed to come first.','The speaker used “firstly” before presenting the opening points.','列举尚未结束时用 lastly 会错误地提示最后一点。'),[Q('lastly',1,1,'Lastly usually introduces?','the final point in a list','the first point in a list','a recent time before now','lastly 是列举最后一点的连接词。'),Q('lastly',2,1,'What did the chair do lastly?','thanked volunteers and closed the meeting','opened the meeting before any discussion','arrived after the expected time','句子中主席感谢志愿者作为最后一项。'),Q('lastly',3,1,'Which sequence is logical?','Firstly, review costs; lastly, approve the plan.','Lastly, begin; first, finish.','Lastly means “in the late afternoon.”','firstly 与 lastly 可以标记首尾顺序。'),Q('lastly',4,1,'For the sense “recently,” English more often uses?','lately or recently','lastly','lathe','lastly 标列举顺序；lately 表示近来。')]);
P('late','Late is an Old English word (læt) meaning slow or delayed; its uses include arriving after the expected time, the later part of a period, and “deceased.”',C('late.s1','课堂出勤','The bus broke down, so Mira was late for class and missed the opening instructions.','公交车抛锚了，因此米拉上课迟到，错过了开场说明。','The bus broke down / so Mira was late for class / and missed / the opening instructions.','late 作表语形容词，搭配 late for class 表示迟到；so 表示原因结果。','她到达时间晚于预期，符合 s1。'),M('Mira was late for class because she arrived twenty minutes before the lesson began.','Mira was early because she arrived before the lesson began.','提前到达不符合 late for class。'),[Q('late',1,1,'If someone is late for class, they arrive?','after the expected time','before the class begins','after the final chapter of a book only','late 表示晚于预期或规定时间。'),Q('late',2,2,'In “the late afternoon,” late means?','near the end of the afternoon','after the right time for class','no longer alive','此处指一个时段的后半段。'),Q('late',3,3,'In “the late president,” late means the president is?','no longer alive','arriving after a scheduled event','the most recent in a sequence','头衔前的 late 可指已故的。'),Q('late',4,4,'In “She works late,” late is used as?','an adverb meaning until a time near the end','a noun meaning family name','an adjective meaning deceased','此处副词 late 修饰 works，表示工作到很晚。')]);
P('lateen','Lateen is adapted from French latine in voile latine, literally “Latin sail,” named for Mediterranean use.',C('lateen.s1','帆船航海','The lateen sail’s long sloping yard held a triangular canvas that helped the dhow sail close to the wind.','三角帆的长斜桁支撑着帆布，帮助单桅帆船迎风航行。','The lateen sail’s long sloping yard / held a triangular canvas / that helped the dhow / sail close to the wind.','lateen 修饰 sail，指斜桁悬挂的三角帆；that 从句说明这种帆的航行作用。','三角帆形状与悬挂方式符合 s1。'),M('The vessel carried a lateen sail with a square canvas hanging from a short horizontal yard.','The vessel carried a lateen sail with a triangular canvas on a long sloping yard.','方形帆和短水平桁与 lateen 的三角形及斜桁特征不符。'),[Q('lateen',1,1,'A lateen sail is typically?','triangular and hung from a long sloping yard','square and hung from a short horizontal yard','a narrow laser beam','lateen 帆是三角形，悬挂在长斜桁上。'),Q('lateen',2,1,'A lateen can also be?','a vessel rigged with a lateen sail','a person’s family name','a recent event in a list','lateen 也可作名词指装有这种帆的船。'),Q('lateen',3,2,'Where did the name lateen come through?','French latine, “Latin sail”','an acronym for amplified light','Old English for “voice box”','lateen 的名称来自法语中“拉丁帆”的说法。'),Q('lateen',4,1,'Which phrase is natural?','a lateen sail on a dhow','a lateen square sail with no sloping yard','a laryngeal sail','lateen 常作定语修饰 sail。')]);
P('lately','Lately is formed from late plus -ly; it means in the recent period, sometimes describing a new pattern.',C('lately.s2','健康记录','Lately, Arun has been waking before dawn more often than he used to, even on weekends.','近来，阿伦比以前更常在黎明前醒来，周末也如此。','Lately / Arun has been waking before dawn / more often than he used to / even on weekends.','句首 lately 修饰整个现在完成进行时，强调近期反复出现的新习惯。','与过去相比最近更常发生，符合 s2。'),M('Lately, the diary describes a pattern from ten years ago that has not occurred at all in the recent period.','The diary recently records the pattern because it has been happening again.','十年前且近期完全未发生的事情不属于 lately 的时间范围。'),[Q('lately',1,1,'Lately means?','in the period just before now','at the final point in a list','at the side of an object','lately 表示最近、近来。'),Q('lately',2,2,'What recent pattern has changed for Arun?','he wakes before dawn more often than before','he stopped waking early ten years ago','he arrives late for class once','句子强调近期比以前更常早醒。'),Q('lately',3,1,'Which phrase is grammatical?','I have not seen her lately.','I lately have saw her yesterday.','Lately means “last in a list.”','lately 常用于现在完成时。'),Q('lately',4,1,'Which word is better for a final list item?','lastly','lately','laterally','lastly 表示列举最后一点。')]);
P('lateness','Lateness is formed from late plus -ness and names the fact or condition of being late.',C('lateness.s1','交通投诉','The airline apologized for the lateness of the flight and offered passengers meal vouchers during the delay.','航空公司为航班延误道歉，并在等待期间向乘客提供餐券。','The airline apologized / for the lateness of the flight / and offered passengers / meal vouchers during the delay.','lateness 是介词 for 的宾语，指晚点这一状态；of the flight 指明对象。','航班未按预期时间到达，符合 s1。'),M('The airline apologized for the lateness of the flight even though it arrived an hour before its scheduled time.','The airline congratulated itself because the flight arrived early.','提前抵达不构成晚点。'),[Q('lateness',1,1,'Lateness is?','the state or fact of being late','the act of arriving early','the last name shared by a family','lateness 指迟到或延误的状态。'),Q('lateness',2,1,'Why did the airline apologize?','the flight was delayed','the flight arrived an hour early','passengers forgot their family names','航班延误导致航空公司道歉。'),Q('lateness',3,1,'Which phrase is natural?','excuse my lateness','excuse my latefully','lateness between two galaxies','excuse my lateness 是自然表达。'),Q('lateness',4,1,'Lateness can also refer to?','the fact that it is already late in the day or hour','a narrow beam of light','a triangular sail','lateness 也可指时辰已晚。')]);
P('latent','Latent comes from Latin latens, “hidden,” from latere, “to lie hidden”; it describes something present but not yet visible or active.',C('latent.s1','疾病筛查','The screening found a latent infection: the pathogen was present, although the patient showed no symptoms.','筛查发现一种潜伏感染：病原体已经存在，但患者尚未出现症状。','The screening found a latent infection / the pathogen was present / although the patient / showed no symptoms.','latent 修饰 infection，表示感染存在但尚未显现；although 引出症状缺失。','病原体存在而未出现症状，符合 s1。'),M('The infection was latent even though it was fully visible, active, and causing obvious symptoms from the beginning.','The infection was active and symptomatic rather than latent.','已经明显活跃并出现症状的感染不是潜伏的。'),[Q('latent',1,1,'A latent condition is?','present but hidden or not yet active','already obvious and fully active','a family name','latent 表示潜在、潜伏的。'),Q('latent',2,1,'Why was the infection called latent?','the pathogen was present without symptoms','the patient showed every symptom immediately','the test found no pathogen at all','病原体存在但无症状，符合 latent。'),Q('latent',3,2,'A “latent fingerprint” is a print that is?','hard to see until it is developed','a printed family name','a machine-generated laser beam','latent 也可指现场不易看见的指纹。'),Q('latent',4,1,'The Latin verb latere means?','to lie hidden','to arrive late','to praise formally','latent 与拉丁语“隐藏”有关。')]);
P('later','Later is the comparative form of late and means at a time after now or after another event.',C('later.s1','出行安排','We can compare the two routes later, after the survey team returns with its travel times.','调查组带回各条路线的行程时间后，我们可以稍后再比较。','We can compare the two routes later / after the survey team returns / with its travel times.','later 作时间副词，表示晚于当前时刻；after 从句说明比较的时间条件。','比较将在团队回来之后进行，符合 s1。'),M('We will compare the routes later before the survey team even leaves, at a time earlier than now.','We will compare the routes earlier, before the survey team leaves.','早于当前计划的时间不是 later。'),[Q('later',1,1,'Later means?','at a time after now or after another event','at the side of something','the final item in every list','later 表示稍后或之后。'),Q('later',2,1,'When will the routes be compared?','after the survey team returns','before the survey team leaves','only during a lateen sail race','later 将比较安排在团队返回之后。'),Q('later',3,1,'Which sentence uses later naturally?','I will call you later this evening.','I later called you tomorrow.','The later is a family name.','later 可表示稍后某时。'),Q('later',4,1,'Later is the comparative form of?','late','latest','lateral','later 是 late 的比较级形式。')]);
P('lateral','Lateral came through French from Latin lateralis, “belonging to the side,” from latus, “side”; deeper Latin origin is uncertain.',C('lateral.s1','神经检查','The physician checked for a lateral movement of the eye while the patient followed a pen from side to side.','医生检查眼睛是否能够横向移动，同时让患者的视线跟随一支笔左右移动。','The physician checked for / a lateral movement of the eye / while the patient followed a pen / from side to side.','lateral 修饰 movement，指向侧边的移动；from side to side 说明方向。','眼球左右移动是侧向移动，符合 s1。'),M('The diagram labeled a movement straight upward as lateral, although it showed no motion toward either side.','The diagram labeled the upward movement as vertical.','垂直向上而不是向两侧的运动不属于 lateral。'),[Q('lateral',1,1,'Lateral means?','at, toward, or from the side','near the end of a period','hidden but present','lateral 指侧面的或向侧方的。'),Q('lateral',2,1,'What movement did the physician check?','the eye moving from side to side','the eye moving only upward','a person arriving after class starts','左右移动属于 lateral movement。'),Q('lateral',3,1,'Which phrase is natural?','a lateral branch on the main road','a lateral direction straight upward only','a laryngeal branch of the calendar','lateral 可描述侧枝或侧向位置。'),Q('lateral',4,1,'The Latin source lateralis means?','belonging to the side','most recent','able to praise','lateralis 意为属于侧边的。')]);
P('laterality','Laterality is formed from lateral plus -ity and names dominance or preference for one side of the body or brain.',C('laterality.s1','神经心理测试','The assessment measured hand laterality by recording which hand each child chose for drawing and throwing.','这项评估通过记录每个孩子用哪只手画画和投掷，测量其手部侧化倾向。','The assessment measured hand laterality / by recording which hand / each child chose / for drawing and throwing.','laterality 指身体一侧或一侧大脑占优势的倾向；by 引出测量方法。','测试比较左右手的偏好，符合 s1。'),M('The test measured laterality although every child used both hands identically and showed no side preference at all.','The test found no hand laterality because neither side was preferred.','没有一侧占优或偏好就不能证明 laterality。'),[Q('laterality',1,1,'Laterality is the dominance or preference for?','one side of the body or brain','the final item in a numbered list','a light beam of one color','laterality 指身体或脑一侧的优势。'),Q('laterality',2,1,'How did the assessment measure hand laterality?','it recorded which hand children chose for tasks','it recorded only their last names','it measured the lateral edge of a book','观察左右手选择可测量手部侧化。'),Q('laterality',3,1,'Which field often studies laterality?','neuroscience or psychology','ship rigging only','laundry services','laterality 常见于神经科学和心理学。'),Q('laterality',4,1,'Laterality is formed from lateral plus?','-ity','-ie','-en','laterality 由 lateral 加 -ity 构成。')]);
P('laterally','Laterally is the adverb form of lateral and means in a direction to the side.',C('laterally.s1','设备调试','Slide the control panel laterally until its edge aligns with the marker on the rail.','将控制面板向侧面滑动，直到边缘与导轨上的标记对齐。','Slide the control panel laterally / until its edge aligns / with the marker / on the rail.','laterally 修饰 slide，指向侧方移动；until 引出停止的条件。','面板沿左右侧方向移动，符合 s1。'),M('The technician moved the panel laterally straight upward, without moving it toward either side.','The technician moved the panel vertically upward.','直线上移是垂直方向，不是侧向的 laterally。'),[Q('laterally',1,1,'To move laterally is to move?','toward the side','toward the end of a list','into a hidden state','laterally 表示向侧方。'),Q('laterally',2,1,'How should the panel move?','sideways along the rail','straight upward away from the rail','after every other panel is gone','语境要求沿导轨侧向移动。'),Q('laterally',3,1,'Which phrase is natural?','shift laterally to the left','shift laterally upward into the sky','lateralize the laterally panel','laterally 可修饰 shift，说明方向。'),Q('laterally',4,1,'The related adjective is?','lateral','latent','lasting','laterally 由 lateral 派生。')]);
P('latest','Latest is the superlative of late and means most recent; in “at the latest,” it means no later than a stated time.',C('latest.s1','科技新闻','The latest update fixes the battery problem reported by users earlier this week.','最新更新修复了用户本周早些时候报告的电池问题。','The latest update / fixes the battery problem / reported by users / earlier this week.','latest 修饰 update，表示时间上最新；reported 短语限定被修复的问题。','更新发生在近期，符合 most recent 义。'),M('The latest report was the oldest one in the archive, written before every other report.','The earliest report was the oldest one in the archive.','最古老、最早的报告不是 latest。'),[Q('latest',1,1,'The latest report is the?','most recent report','oldest report in the archive','report that arrives after a meeting starts','latest 指时间上最新的。'),Q('latest',2,1,'What does “at the latest by Friday” mean?','no later than Friday','only after Friday has passed','sometime before last year','at the latest 给出不晚于的截止时间。'),Q('latest',3,1,'Which phrase is natural?','the latest software update','the latest update from ten years ago when newer ones exist','a latest than the old model','latest 可修饰 update。'),Q('latest',4,1,'Latest is the superlative form related to?','late','lateral','lately','latest 是 late 的最高级形式。')]);

P('latex','Latex is recorded from the 17th century for a milky plant fluid; its history is traced through Latin latex, “liquid.”',C('latex.s1','材料科学','Workers wore protective gloves because the elastic coating contained natural latex from rubber trees.','由于这种弹性涂层含有来自橡胶树的天然乳胶，工人戴上了防护手套。','Workers wore protective gloves / because the elastic coating contained / natural latex / from rubber trees.','latex 作不可数名词，指植物乳液及其制成的材料；because 引出防护原因。','天然乳胶来自植物并用于制造材料，符合 s1。'),M('The gloves contained latex even though they were made entirely from metal and contained no plant-derived material.','The gloves contained no latex because they were made entirely from metal.','纯金属手套不含乳胶。'),[Q('latex',1,1,'Natural latex is a milky liquid obtained from?','some plants such as rubber trees','a metal lathe','a person’s voice box','latex 可指从植物取得的乳液。'),Q('latex',2,1,'Why did the workers wear gloves?','the coating contained natural latex','the coating was only a family name','the gloves contained no material','防护手套用于接触含乳胶的材料。'),Q('latex',3,1,'Which phrase is natural?','latex gloves','a latex of degrees north','latex the machine into a bowl','latex 常作材料名词，如 latex gloves。'),Q('latex',4,1,'The word latex has a historical connection with Latin for?','liquid','last in a list','praise','词源与拉丁语 latex“液体”有关。')]);
P('lathe','Lathe is a Germanic word of uncertain origin, probably entering English through Old Norse; it names a machine that turns a workpiece against a tool.',C('lathe.s1','木工车间','The carpenter mounted the chair leg on a lathe and turned it until the surface was smooth and evenly rounded.','木工把椅子腿固定在车床上旋转加工，直到表面光滑且均匀圆润。','The carpenter mounted the chair leg / on a lathe / and turned it / until the surface was smooth and evenly rounded.','lathe 作介词 on 的宾语，指旋转工件的机床；until 引出加工结果。','工件旋转并由刀具加工，符合 s1。'),M('The carpenter shaped the chair leg on a lathe while the workpiece stayed motionless and no cutting tool was used.','The carpenter shaped the leg on a lathe by rotating it against a cutting tool.','工件不旋转且没有刀具加工，不符合车床的工作方式。'),[Q('lathe',1,1,'A lathe is a machine that?','rotates a workpiece against a cutting tool','measures north or south of the equator','produces a narrow beam of light','lathe 是旋转工件供刀具加工的机床。'),Q('lathe',2,1,'What was turned on the lathe?','a chair leg','a family name','the patient’s larynx','木工在车床上加工椅子腿。'),Q('lathe',3,1,'Which sentence uses lathe as a noun?','The bowl was shaped on a lathe.','The carpenter lathed the bowl until smooth.','She laterally moved the panel.','a lathe 是机器名词。'),Q('lathe',4,2,'The less common verb lathe means?','shape an object on a lathe','arrive after the expected time','praise someone formally','lathe 也可作动词，指用车床加工。')]);
P('lather','Lather is an English noun and verb for the foam produced when soap mixes with water, or the act of producing that foam.',C('lather.s1','洗手步骤','She added a little water and rubbed the soap between her palms until a thick lather formed.','她加了少量水，在掌心揉搓肥皂，直到形成浓密泡沫。','She added a little water / and rubbed the soap / between her palms / until a thick lather formed.','lather 在此作不可数名词，指肥皂泡沫；until 引出揉搓后的结果。','肥皂与水混合形成泡沫，符合 s1。'),M('The soap produced a thick lather while it remained completely dry and was never mixed with water.','The soap stayed dry, so it produced no lather.','没有水参与且保持干燥时不会产生泡沫。'),[Q('lather',1,1,'Lather is the foam produced when?','soap mixes with water','a lathe turns a workpiece','lava cools into rock','lather 指肥皂与水混合产生的泡沫。'),Q('lather',2,1,'How did she make the lather?','she rubbed wet soap between her palms','she kept the soap dry and untouched','she turned it on a lathe','加水揉搓肥皂形成泡沫。'),Q('lather',3,1,'Which sentence uses lather as a verb?','Lather your hands before rinsing them.','A thick lather formed in the bowl.','The lateen crossed the harbour.','第一句中 lather 表示起泡或涂上泡沫。'),Q('lather',4,1,'Which phrase is natural?','a thick lather of soap','a lather of latitude and longitude','a lather to the north of the equator','a lather of soap 是自然搭配。')]);
P('latifundium','Latifundium is a Latin historical term for a large landed estate; its plural is latifundia.',C('latifundium.s1','古罗马经济','The historian described the valley as a latifundium worked by dependent laborers rather than divided among small farmers.','历史学家把这片山谷描述为由依附劳动者耕作的大庄园，而不是分给小农。','The historian described the valley / as a latifundium / worked by dependent laborers / rather than divided among small farmers.','latifundium 作表语名词，指大型庄园；过去分词短语说明劳动力结构。','土地集中在一个大庄园并由依附劳工经营，符合 s1。'),M('The historian called each tiny independent family garden a latifundium although none was a large estate.','The historian called the valley a group of smallholdings because each family owned a tiny plot.','零散小农地不是大型庄园。'),[Q('latifundium',1,1,'A latifundium is?','a great landed estate','a small personal garden','a machine that shapes wood','latifundium 指大型庄园。'),Q('latifundium',2,1,'Who worked the estate in the example?','dependent laborers','only independent owners of tiny plots','a team of laser technicians','语境强调依附劳动者耕作。'),Q('latifundium',3,1,'What is the plural of latifundium?','latifundia','latifundiums only','latitudines','常见复数形式是 latifundia。'),Q('latifundium',4,1,'Latifundium is mainly used in?','historical and social discussion','everyday talk about a bathroom','medical description of the voice box','该词主要是历史和社会学术语。')]);
P('Latin','Latin continues Latinus, “Latin, Roman,” associated with Latium around Rome; it is a noun for the language and an adjective for related people or things.',C('Latin.s1','医学词汇','Many anatomical terms were borrowed from Latin, the classical language used by scholars across Europe.','许多解剖学术语借自拉丁语，这种古典语言曾被欧洲各地的学者使用。','Many anatomical terms / were borrowed from Latin / the classical language / used by scholars across Europe.','Latin 作介词 from 的宾语，指语言；同位语说明其历史地位。','句中 Latin 指罗马古典语言，符合 s1。'),M('The inscription is in Latin, the language spoken today by most residents of modern Rome at home.','The inscription is in Latin, the classical language of ancient Rome.','现代罗马居民日常语言不是古典拉丁语。'),[Q('Latin',1,1,'Latin as a noun most often names?','the classical language of Rome','a family surname in every country','a device for turning wood','Latin 可作语言名。'),Q('Latin',2,2,'In “Latin script,” Latin is used as?','an adjective describing the alphabet or writing system','a verb meaning praise','a noun for a late arrival','Latin 在此修饰 script。'),Q('Latin',3,1,'Which sentence is correct?','Medical vocabulary often comes from Latin.','She speaks a Latin fluently yesterday.','Latin is a machine that rotates a tool.','语言名 Latin 作不可数名词。'),Q('Latin',4,1,'Latin is historically associated with?','Latium and ancient Rome','the larynx and vocal folds','the equator and degrees of latitude','Latinus 与意大利中部的 Latium 及罗马有关。')]);
P('latitude','Latitude comes from Latin latitudo, “breadth”; it names geographic distance north or south of the equator and, figuratively, freedom to choose.',C('latitude.s1','地图定位','The research station lies at latitude 62 degrees north, well above the city where the team began its journey.','研究站位于北纬62度，远在团队出发城市以北。','The research station lies / at latitude 62 degrees north / well above the city / where the team began its journey.','latitude 与角度及 north 连用表示纬度；where 从句限定出发城市。','北纬度数测量赤道以北的位置，符合 s1。'),M('The map gave the city’s latitude as 62 degrees east of Greenwich.','The map gave the city’s longitude as 62 degrees east of Greenwich.','相对格林尼治向东测量的是经度，不是纬度。'),[Q('latitude',1,1,'Geographic latitude measures a point’s distance?','north or south of the equator','east or west of Greenwich','from the nearest ocean floor','纬度表示相对赤道的南北位置。'),Q('latitude',2,2,'“Teachers have latitude in grading” means they have?','some freedom to decide','a precise location north of the equator','a fixed list with no choice','latitude 的比喻义是自由裁量余地。'),Q('latitude',3,1,'Which notation indicates latitude?','40 degrees north','40 degrees east of Greenwich','40 degrees of rainfall','北纬40度属于纬度表示。'),Q('latitude',4,2,'Latitude can figuratively mean?','freedom or room to make a choice','the final item in a sequence','a narrow beam of light','latitude 也可比喻选择空间。')]);
P('latter','Latter comes from Old English lætra, the comparative related to late; it means the second of two mentioned or nearer the end of a period.',C('latter.s1','两种方案比较','The board considered renting or buying the building and chose the latter because its long-term costs were lower.','董事会考虑租用或购买这栋楼，最后选择了后者，因为长期成本更低。','The board considered renting or buying the building / and chose the latter / because its long-term costs / were lower.','the latter 回指刚提到的两项中的第二项 buying；because 给出选择理由。','租与买中选择第二项，符合代词义 s1。'),M('The board considered renting first and buying second, then chose the latter, meaning renting.','The board chose the former, meaning renting, or the latter, meaning buying.','latter 指后提到的 buying，不是先提到的 renting。'),[Q('latter',1,1,'The latter of two options is?','the second one mentioned','the first one mentioned','the most recent event in every context','latter 指两者中后提到的一个。'),Q('latter',2,2,'In “the latter half of the year,” latter means?','nearer the end of the period','the first half before the year begins','the most recent night','该形容词义表示时期较后半段。'),Q('latter',3,1,'Renting and buying were discussed; choosing the latter means choosing?','buying','renting','neither option','buying 是后提到的选项。'),Q('latter',4,2,'Which phrase is natural?','in the latter part of the century','the latter of five items with no two-item contrast','latter means arriving late for class','latter 常指两项中的后者或时期后段。')]);
P('laud','Laud comes from Latin laudare, “praise”; as a verb it means to praise formally, and as a noun it can mean high praise.',C('laud.s1','文学评论','Reviewers lauded the debut novel for its careful portraits of ordinary families.','评论家称赞这部处女作细致刻画了普通家庭。','Reviewers lauded the debut novel / for its careful portraits / of ordinary families.','lauded 是及物动词过去式；for 引出受到赞扬的原因。','评论家正式称赞作品的刻画方式，符合 s1。'),M('The reviewers lauded the novel by condemning it as careless and unworthy of any praise.','The reviewers criticized the novel as careless rather than lauding it.','谴责作品而非称赞与 laud 的含义相反。'),[Q('laud',1,1,'To laud a novel is to?','praise it','file a lawsuit about it','shape it on a lathe','laud 作动词表示赞扬。'),Q('laud',2,1,'Why did reviewers laud the novel?','its portraits of families were carefully drawn','it contained no characters or writing','it was a leaking pipe','评论家因人物刻画而称赞作品。'),Q('laud',3,1,'Which phrase is natural?','critics lauded the performance','critics lauded the performance by calling it worthless','laud the review into a lathe','laud 的宾语通常是受到称赞的人或事。'),Q('laud',4,2,'As a noun, laud can mean?','high praise','a legal claim in court','a side direction','laud 也可作名词指赞誉。')]);
P('laudable','Laudable comes from Latin laudabilis, “praiseworthy,” from laudare, “to praise”; it describes an action or aim that deserves praise.',C('laudable.s2','公益倡议','Their laudable goal was to provide clean drinking water to every household in the remote district.','他们值得称道的目标是为偏远地区的每户人家提供清洁饮用水。','Their laudable goal / was to provide clean drinking water / to every household / in the remote district.','laudable 修饰 goal，评价其目的高尚；to provide 说明目标内容。','为所有家庭提供饮水是崇高且值得称赞的目标，符合 s2。'),M('The committee called the goal laudable even though it was designed to deny clean water to every household.','The committee rejected the goal because it would deny clean water to households.','故意剥夺饮水的目标并不值得称赞。'),[Q('laudable',1,1,'A laudable effort is one that?','deserves praise','deserves blame','is merely the second of two choices','laudable 表示值得称赞的。'),Q('laudable',2,1,'Why was the water project laudable?','it aimed to provide clean water to every household','it aimed to deny water to the district','it was a machine for cutting wood','目标为居民改善饮水，值得肯定。'),Q('laudable',3,1,'Which phrase is natural?','a laudable attempt to reduce waste','a laudable act of deliberate harm','a laudable, meaning “last in a list”','laudable 常修饰努力、目标或行动。'),Q('laudable',4,2,'Laudable can also suggest a purpose is?','noble or worthy in motive','hidden and inactive','not strict about rules','词条第二义强调目的高尚。')]);
P('laugh','Laugh is an Old English verb and noun for expressing amusement; in “laugh off,” it means to treat criticism or a problem as unimportant.',C('laugh.s2','团队复盘','When the team noticed a minor typo on the poster, Hana laughed it off and corrected the file without blaming anyone.','团队发现海报上有个小拼写错误时，哈娜一笑置之，直接改好文件，没有责怪任何人。','When the team noticed a minor typo / Hana laughed it off / and corrected the file / without blaming anyone.','laughed it off 是短语动词，表示把小问题当作不重要；and 连接反应与处理。','她没有把失误看得很严重，而是轻松处理，符合 s2。'),M('Hana laughed off the typo by treating it as a catastrophe and demanding an emergency investigation.','Hana took the typo seriously and demanded an urgent investigation.','把小错当作灾难并严肃追究并非 laugh it off。'),[Q('laugh',1,1,'To laugh off a mistake means to?','treat it as unimportant and not be upset','make a sound of amusement at a joke only','praise it formally','laugh off 表示对某事一笑置之。'),Q('laugh',2,2,'How did Hana respond to the typo?','she corrected it calmly without blaming anyone','she treated it as a catastrophe','she launched a satellite','她轻松处理错误而没有责怪他人。'),Q('laugh',3,3,'In “Everyone laughed at the joke,” laugh means?','make a sound showing amusement','dismiss an accusation as unimportant','tie cargo to a deck','laugh at a joke 是发笑之义。'),Q('laugh',4,2,'A “good laugh” uses laugh as a?','noun meaning an amusing experience or the sound','verb meaning launch a product','noun meaning a family name','laugh 也可作名词表示一笑或有趣的事。')]);
P('laughter','Laughter is an uncountable noun from laugh and means the action or sound of laughing.',C('laughter.s1','聚会气氛','A burst of laughter spread through the room when the host imitated the parrot’s dramatic greeting.','主人模仿鹦鹉夸张的问候时，笑声在屋里传开。','A burst of laughter / spread through the room / when the host imitated / the parrot’s dramatic greeting.','laughter 作不可数名词，前面用 a burst of 描述一阵笑声；when 引出原因。','整个房间响起笑声，符合 s1。'),M('The room filled with a laughter after the joke.','The room filled with laughter after the joke.','laughter 通常为不可数名词，不用不定冠词 a。'),[Q('laughter',1,1,'Laughter is?','the action or sound of laughing','a machine that emits a beam','a list of family names','laughter 指发笑的动作或声音。'),Q('laughter',2,1,'What caused laughter in the room?','the host imitated the parrot','the host read a silent blank page','a court filed a lawsuit','模仿鹦鹉的问候让大家发笑。'),Q('laughter',3,1,'Which phrase is standard?','a burst of laughter','a laughter after every joke','the laughter are loud','常说 a burst of laughter，而 laughter 通常不可数。'),Q('laughter',4,1,'Which word is the verb?','laugh','laughter','laureate','laugh 是动词，laughter 是名词。')]);
P('launch','Launch is from Anglo-French/Old French forms meaning to throw or set going; it now covers sending spacecraft, introducing products, and putting boats into water.',C('launch.s2','产品发布','The company will launch its new translation app next month after completing the final security review.','公司将在完成最后一轮安全审查后，于下月推出新的翻译应用。','The company will launch its new translation app / next month / after completing / the final security review.','launch 是及物动词，表示公开推出产品；after 引出发布前需完成的步骤。','正式向市场推出新应用，符合 s2。'),M('The company launched its new app by keeping it secret and unavailable to every customer.','The company announced and released its new app to the public.','完全保密且未向用户开放不属于公开推出。'),[Q('launch',1,2,'To launch a product is to?','introduce it publicly','tie it to a deck with rope','arrive after the expected time','launch s2 指公开推出产品。'),Q('launch',2,2,'What must happen before the app launch?','the final security review must be completed','the app must be erased before release','a boat must be put into the sea','语境中的产品发布须先完成安全审查。'),Q('launch',3,1,'A rocket launch means?','sending the rocket up','releasing a new phone to stores','putting a boat into water','火箭发射对应 launch s1。'),Q('launch',4,3,'A ship launch can mean?','putting a new boat into the water','writing a last name','making a narrow beam of light','launch s3 指新船下水。')]);
P('launcher','Launcher is formed from launch plus -er and names a device that sends a rocket or other object on its way.',C('launcher.s1','航天发射','Technicians inspected the launcher before loading the small research rocket onto its guide rail.','技术人员在把小型科研火箭装上导轨前，检查了发射装置。','Technicians inspected the launcher / before loading the small research rocket / onto its guide rail.','launcher 作 inspected 的宾语，指用于发射的装置；before 表示装载前的检查。','发射装置为火箭提供起始支撑，符合 s1。'),M('The launcher was the rocket itself, while no device or structure was used to send it on its way.','The launcher was the device that supported and sent the rocket at launch.','火箭本身与发射装置不是同一物件。'),[Q('launcher',1,1,'A rocket launcher is?','a device used to send the rocket on its way','the family name of the technician','a book’s last chapter','launcher 指发射火箭或物体的设备。'),Q('launcher',2,1,'What did technicians inspect?','the device and its guide rail','the rocket’s laughter','the technician’s latitude','他们检查的是发射装置。'),Q('launcher',3,1,'Which phrase is natural?','a mobile app launcher','a launcher that is the same thing as the launched rocket in every case','a launcher of a larynx','launcher 也可指软件启动器。'),Q('launcher',4,1,'Launcher is formed from launch plus?','-er','-ness','-ity','-er 可构成执行或承担功能者的名词。')]);
P('launderette','Launderette is a British English coinage from laundry plus -ette; it means a shop where customers pay to use washing machines.',C('launderette.s1','城市生活','The launderette stayed open late so residents in the apartment block could wash their clothes after work.','这家自助洗衣店营业到很晚，公寓楼的居民可以下班后去洗衣服。','The launderette stayed open late / so residents in the apartment block / could wash their clothes / after work.','launderette 作主语名词，指付费使用洗衣机的店；so 引出营业时间安排的用途。','居民到店里付费洗衣，符合 s1。'),M('She went to the launderette to buy a family surname for her application.','She went to the launderette to use a washing machine.','launderette 是洗衣店，不是姓氏服务机构。'),[Q('launderette',1,1,'A launderette is a place where customers?','pay to use washing machines','receive a new surname','watch a rocket launch','launderette 指自助洗衣店。'),Q('launderette',2,1,'Why did the shop stay open late?','residents needed to wash clothes after work','the shop was a legal court','the shop sold larynxes','居民下班后可来洗衣。'),Q('launderette',3,1,'Which variety especially uses launderette?','British English','only Latin','only medical English','launderette 是英式英语常用词。'),Q('launderette',4,1,'A common American equivalent is?','laundromat','latifundium','laureate','laundromat 是常见美式对应词。')]);
P('laundry','Laundry comes through French/Medieval Latin washing-house terms and can mean clothes to be washed or a place/business that washes them.',C('laundry.s1','家庭日常','He separated the dark laundry from the white clothes before starting the washing machine.','启动洗衣机前，他把深色待洗衣物与白色衣物分开。','He separated the dark laundry / from the white clothes / before starting / the washing machine.','laundry 作宾语，指待洗衣物；from 引出与其分开的衣物。','衣物等待清洗，符合 s1。'),M('She put the clean folded laundry in the washing machine because she planned to wash it again.','She put the dirty laundry in the washing machine and stored the clean clothes away.','已经干净叠好的衣物不是待洗 laundry。'),[Q('laundry',1,1,'Laundry can mean?','clothes that are to be washed or have just been washed','a machine that shapes chair legs','a formal prize winner only','laundry 可指衣物。'),Q('laundry',2,1,'What did he separate before washing?','dark laundry from white clothes','the larynx from the vocal folds','the last name from a surname','他按颜色分拣待洗衣物。'),Q('laundry',3,1,'Which phrase is natural?','do the laundry','do a laundry of one shirt as a count noun','laundry the law formally','do the laundry 是常见表达。'),Q('laundry',4,2,'Laundry can also mean?','a business or room where clothes are washed','a triangle sail','a legal rule','laundry 也可指洗衣业务或场所。')]);
P('laureate','Laureate comes from Latin laureatus, “crowned with laurel”; as a noun it names someone honored with a prize or title.',C('laureate.s1','颁奖典礼','The laureate read a new poem after accepting the national literature prize.','这位获奖者接受国家文学奖后朗诵了一首新诗。','The laureate read a new poem / after accepting / the national literature prize.','laureate 作主语名词，指获奖或获授荣誉头衔的人；after 引出领奖后的活动。','获文学奖的人符合 s1。'),M('The laureate received no prize or title and was merely a visitor who had entered the hall by mistake.','The laureate was the person honored with the prize.','没有获得荣誉称号或奖项的人不符合此名词义。'),[Q('laureate',1,1,'A laureate is someone?','honored with a prize or title','who operates a laundry','who arrives after class begins','laureate 指获奖或获授头衔者。'),Q('laureate',2,1,'What did the laureate do after accepting the prize?','read a new poem','launched a satellite','repaired the lathe','获奖者在仪式上朗诵诗歌。'),Q('laureate',3,1,'Which phrase is natural?','a Nobel laureate','a laureate who has never received an honor','a launderette laureate machine','Nobel laureate 是常见搭配。'),Q('laureate',4,2,'Laureate can also be an adjective meaning?','crowned with laurel or honored','late in the evening only','having loose discipline','该词也可作形容词表示受桂冠荣誉的。')]);
P('laurel','Laurel comes from Latin laurus, the evergreen tree whose leaves crowned victors; plural laurels also means honors earned by achievement.',C('laurel.s2','职业成就','After winning the design award, Inez kept taking on difficult projects instead of resting on her laurels.','赢得设计奖后，伊内兹仍不断接受有挑战的项目，而没有躺在荣誉上止步不前。','After winning the design award / Inez kept taking on difficult projects / instead of resting / on her laurels.','laurels 用复数比喻已获得的荣誉；rest on one’s laurels 表示因过去成绩而停止努力。','她没有满足于既有奖项，符合 s2。'),M('After one prize, Inez rested on her laurels by continuing to work hard and seeking new challenges.','After one prize, Inez continued striving instead of resting on her laurels.','继续努力而非停下，恰恰不是 rest on laurels。'),[Q('laurel',1,2,'In “rest on one’s laurels,” laurels means?','honors or achievements already won','laundry waiting to be washed','a family surname','laurels 比喻已取得的荣誉。'),Q('laurel',2,2,'What did Inez do after winning the award?','kept accepting difficult projects','stopped working because the award was enough','turned her project on a lathe','她继续挑战新项目，没有满足于过去荣誉。'),Q('laurel',3,1,'A laurel can also be?','an evergreen shrub or tree','a laser device','a law court claim','laurel 也指常绿灌木或树。'),Q('laurel',4,2,'Which phrase is idiomatic?','rest on your laurels','rest on your last name','rest on your lathe','rest on your laurels 是固定表达。')]);
P('lava','Lava came from Italian lava, “torrent or stream,” applied to molten rock from volcanoes; a proposed deeper derivation remains uncertain.',C('lava.s1','火山地貌','Fresh lava flowed from the vent and slowly cooled as it spread across the lower slope.','新熔岩从火山口流出，在向较低山坡蔓延时逐渐冷却。','Fresh lava flowed from the vent / and slowly cooled / as it spread / across the lower slope.','lava 指火山喷出的熔融岩石；as 表示蔓延和冷却同时发生。','从火山口流出的熔融岩石符合 s1。'),M('Lava poured from the volcano as a cold solid block that had never melted.','Molten lava poured from the volcano and cooled into solid rock.','未熔化的冷固体不是喷出的 lava。'),[Q('lava',1,1,'Lava is?','hot melted rock flowing from a volcano','a language spoken in ancient Rome','a machine for turning wood','lava 指火山喷出的熔岩。'),Q('lava',2,1,'What happened to the fresh lava on the slope?','it spread and gradually cooled','it remained frozen and never moved','it turned into a last name','熔岩流动并逐渐冷却。'),Q('lava',3,2,'After lava cools and hardens, the word can also refer to?','the rock formed from it','the machine that shapes it','the people who launch it','lava 也可指熔岩冷却后形成的岩石。'),Q('lava',4,1,'The name lava came into English through?','Italian','Old English for voice box','French for surname','该词经意大利语进入英语。')]);
P('lavatory','Lavatory comes from Late Latin lavatorium, “place for washing,” from lavare, “wash”; English uses it for a room with a toilet and sometimes the bowl itself.',C('lavatory.s1','公共建筑指引','A sign directs visitors to the lavatory at the end of the corridor beside the accessible entrance.','指示牌把访客引到走廊尽头、无障碍入口旁的洗手间。','A sign directs visitors / to the lavatory / at the end of the corridor / beside the accessible entrance.','lavatory 作介词 to 的宾语，指洗手间；后续地点短语指明位置。','访客被指引前往设有厕所的房间，符合 s1。'),M('The sign points to the lavatory, a room where visitors are expected to sleep overnight.','The sign points to the lavatory, the room with toilet facilities.','洗手间不是供访客过夜睡觉的房间。'),[Q('lavatory',1,1,'A public lavatory is?','a room with a toilet','a shop for paid washing machines','a family name on a form','lavatory 指有厕所的房间。'),Q('lavatory',2,1,'Where was the lavatory in the building?','at the corridor end by the accessible entrance','inside the volcano vent','on the north side of the equator','标牌说明洗手间的位置。'),Q('lavatory',3,1,'Which phrase is natural?','Where is the lavatory?','Where is a lavatory for storing laundry only?','The lavatory launched at noon.','询问厕所位置是自然用法。'),Q('lavatory',4,2,'Lavatory can also refer to?','the toilet bowl itself','a person honored with a prize','a great landed estate','该词也可指马桶本身。')]);
P('lave','Lave is an old literary verb from Old English lafian, “wash by pouring water”; Latin lavare may also have influenced it.',C('lave.s1','海岸描写','At high tide, small waves laved the stone steps and left a thin line of foam behind.','涨潮时，细浪轻轻拍洗石阶，并留下了一道薄薄的泡沫。','At high tide / small waves laved the stone steps / and left / a thin line of foam behind.','laved 是文学用语动词，描写水轻拍或洗濯物体；and 连接动作与结果。','海浪轻轻拍打石阶，符合 s1 的水流义。'),M('The waves laved the steps while remaining hundreds of miles away and never touching them.','The waves laved the steps by washing gently over them.','没有接触石阶的海浪不能轻拍或冲洗它们。'),[Q('lave',1,1,'To lave something is to?','wash it or let water lap against it','praise it in a formal speech','measure its distance from the equator','lave 指洗濯或水拍打。'),Q('lave',2,1,'What did the waves do to the steps?','gently washed over them','tied them to a ship with rope','turned them on a lathe','浪轻轻拍洗石阶。'),Q('lave',3,1,'Lave is best described as?','a literary or old-fashioned verb','a common modern word for a surname','a type of legal claim','lave 是较旧或文学性用词。'),Q('lave',4,1,'Which sentence uses lave naturally?','Water laved the shore at dusk.','The shore laved the water into a family name.','The water laved a laser from the lathe.','水可以 l ave 海岸，即轻拍或洗濯海岸。')]);

P('lavish','Lavish as an adjective comes through Old French lavasse, “torrent or deluge”; the verb later developed the sense “bestow profusely.”',C('lavish.s3','导师关怀','The mentor lavished attention on the new researchers, reviewing their drafts and answering questions after hours.','导师给予新研究员大量关注，下班后仍审阅草稿并回答问题。','The mentor lavished attention / on the new researchers / reviewing their drafts / and answering questions after hours.','lavished 是及物动词，意为大量给予；attention 是其宾语。','导师投入大量时间和关怀，符合 s3。'),M('The mentor lavished attention on the researchers by refusing to answer questions or review any work.','The mentor ignored the researchers instead of lavishing attention on them.','拒绝关注与大量给予关怀相反。'),[Q('lavish',1,3,'To lavish attention on someone is to?','give them a great deal of attention','avoid them completely','arrive late to meet them','lavish 作动词表示大量给予。'),Q('lavish',2,3,'How did the mentor lavish attention?','reviewed drafts and answered questions after hours','refused all contact','filed a lawsuit against every researcher','导师投入大量时间帮助研究员。'),Q('lavish',3,1,'A lavish party is usually?','expensive and generous in scale','small and lacking any food','a court procedure','形容词 lavish 可表示奢华且丰盛。'),Q('lavish',4,3,'Which phrase is natural?','lavish praise on a volunteer','lavish a volunteer by ignoring them','lavish is only a noun','lavish praise on 是“给予大量赞扬”。')]);
P('law','Law comes from Old English lagu, borrowed from Old Norse lag, “something laid down”; it can mean a legal system, a particular rule, natural principle, or the profession.',C('law.s1','公民教育','The class discussed how the law protects tenants from being evicted without the required notice.','课堂讨论了法律如何保护租户，使他们不会在未收到规定通知时被驱逐。','The class discussed / how the law protects tenants / from being evicted / without the required notice.','the law 指一国必须遵守的规则体系；how 引出法律的作用。','讨论的是具有约束力的社会法律体系，符合 s1。'),M('The tenants obeyed the law by ignoring every legal rule and refusing to follow a court order.','The tenants obeyed the law by following the valid court order.','无视法律规则并拒绝法院命令不属于守法。'),[Q('law',1,1,'The law as a system is?','the rules people in a country must obey','a thin sheet of metal','a triangle-shaped sailing rig','law 可指整个法律规则体系。'),Q('law',2,2,'In “Parliament passed a law,” law means?','one particular rule made by government','the study of legal practice','the physical force of gravity','该句 law 指一项具体法规。'),Q('law',3,3,'A scientific law describes?','a regular pattern in nature or a field of study','a court claim against a company','a family name','law 也可指自然或科学规律。'),Q('law',4,4,'“She wants to study law” means she wants to study?','the legal profession or subject','the grass on a garden lawn','the history of a lateen sail','study law 指学习法律专业。')]);
P('law enforcement','Law enforcement is the compound noun for officials and agencies responsible for ensuring that laws are obeyed.',C('law enforcement.s1','公共安全','Law enforcement officers closed the road while firefighters cleared debris from the bridge.','消防员清理桥上残骸时，执法人员封闭了道路。','Law enforcement officers closed the road / while firefighters cleared debris / from the bridge.','law enforcement 作复合定语修饰 officers；while 表示两组人员同步行动。','执法人员依法维护秩序和安全，符合 s1。'),M('Law enforcement officers upheld the rules by ordering everyone to ignore all laws and court decisions.','Law enforcement officers upheld the rules by enforcing valid laws.','要求所有人无视法律，不是执行法律。'),[Q('law enforcement',1,1,'Law enforcement refers to?','officials and agencies that make sure laws are obeyed','people who repair a wooden lathe','a group of sports teams','law enforcement 指执法机关及人员。'),Q('law enforcement',2,1,'What did law enforcement officers do in the example?','closed the road during bridge cleanup','washed clothes in a launderette','measured geographic latitude','执法人员封路以保障清理工作。'),Q('law enforcement',3,1,'Which phrase is natural?','law enforcement agencies','law enforce a person into a court','a launderette enforcement officer','law enforcement 可修饰 agencies。'),Q('law enforcement',4,1,'Law enforcement aims to ensure that?','laws are obeyed','every law is ignored','all disputes become lawsuits','执法旨在确保法律得到遵守。')]);
P('lawful','Lawful is formed from law plus -ful and means allowed or recognized by law.',C('lawful.s1','租赁协议','The tenant made a lawful request for repairs after the heating system failed during winter.','供暖系统在冬季故障后，租户依法提出了维修请求。','The tenant made a lawful request / for repairs / after the heating system failed / during winter.','lawful 修饰 request，表示请求在法律允许或认可范围内；after 引出原因。','租户依法申请必要维修，符合 s1。'),M('The court described the entry as lawful even though officers entered the home without permission or legal authority.','The court ruled the entry unlawful because officers had no permission or legal authority.','没有授权的进入不是 lawful。'),[Q('lawful',1,1,'A lawful action is?','allowed or recognized by law','forbidden by every legal rule','a final item in a list','lawful 指合法的。'),Q('lawful',2,1,'Why was the tenant’s repair request lawful?','it was permitted under the rental rules','the tenant broke into the building','the request concerned a family surname','依法要求维修符合租赁规则。'),Q('lawful',3,1,'Which phrase is natural?','a lawful search authorized by a judge','a lawful act that violates all laws','lawfully means “at the side”','lawful 可修饰经批准的搜查。'),Q('lawful',4,1,'Lawful is formed from law plus?','-ful','-ness','-ee','-ful 构成表示具有某性质的形容词。')]);
P('lawlessness','Lawlessness is formed from lawless plus -ness and means a state in which people do not obey the law.',C('lawlessness.s1','灾后治理','After the storm destroyed the local offices, the mayor restored patrols quickly to prevent lawlessness.','风暴摧毁当地办事处后，市长迅速恢复巡逻以防止无法无天的局面。','After the storm destroyed the local offices / the mayor restored patrols quickly / to prevent lawlessness.','lawlessness 作 prevent 的宾语，表示缺乏法律秩序；to prevent 说明恢复巡逻的目的。','灾后机构失灵可能导致人们不守法，符合 s1。'),M('The town descended into lawlessness while every resident followed the laws and authorities maintained full order.','The town maintained order because residents obeyed the law and authorities functioned.','人人守法且秩序稳定与 lawlessness 相反。'),[Q('lawlessness',1,1,'Lawlessness is a state in which?','people do not obey the law','every person follows every legal rule','a legal prize is awarded','lawlessness 指无法无天或缺乏法纪。'),Q('lawlessness',2,1,'Why did the mayor restore patrols?','to prevent disorder after local offices were destroyed','to encourage residents to ignore the law','to launch a new product','巡逻用于防止灾后失序。'),Q('lawlessness',3,1,'Which phrase is natural?','a period of lawlessness','lawlessness where every rule is obeyed','lawlessful government','lawlessness 可指社会失序时期。'),Q('lawlessness',4,1,'The suffix -ness turns lawless into a?','noun naming a state or quality','verb meaning praise','comparative adjective','-ness 把形容词转成状态名词。')]);
P('lawn','Lawn for a mowed grassy area came through Middle English launde and Old French lande, “clearing or open ground”; a separate old word meant fine linen.',C('lawn.s1','庭院维护','They planted clover in the lawn to reduce watering and attract pollinators to the garden.','他们在草坪里种植三叶草，以减少浇水并吸引传粉者到花园。','They planted clover / in the lawn / to reduce watering / and attract pollinators to the garden.','lawn 指修剪维护的草地；to reduce 与 attract 并列说明种植目的。','庭院里种草并维护的区域符合 s1。'),M('The children played on the lawn, a paved indoor hallway with no grass or outdoor space.','The children played on the lawn, the grassy area in the garden.','没有草地的室内走廊不是 lawn。'),[Q('lawn',1,1,'A lawn is usually?','an area of short grass in a garden or park','a room with a toilet','a metal-cutting machine','lawn 指草坪。'),Q('lawn',2,1,'Why did they plant clover in the lawn?','to reduce watering and attract pollinators','to make the lawn a court of law','to turn the grass into a family name','三叶草可减少浇水并吸引传粉昆虫。'),Q('lawn',3,1,'Which phrase is natural?','mow the lawn','mow the lawn with a lawsuit','lawn a family surname','mow the lawn 是常见搭配。'),Q('lawn',4,2,'Lawn historically also named?','a fine linen or cotton fabric','a rocket launcher','the second of two options','lawn 有一个独立的旧义，指细薄亚麻或棉布。')]);
P('lawsuit','Lawsuit combines law and suit; it means a legal claim brought by one side against another in court, or the dispute being decided.',C('lawsuit.s1','商业纠纷','The supplier filed a lawsuit against the manufacturer after repeated attempts to settle the unpaid invoices failed.','多次尝试解决未付款发票问题失败后，供应商起诉了制造商。','The supplier filed a lawsuit / against the manufacturer / after repeated attempts / to settle the unpaid invoices failed.','file a lawsuit against 是提起诉讼的常见搭配；after 引出起诉的背景。','一方向法院提出法律主张，符合 s1。'),M('The supplier filed a lawsuit by privately agreeing to settle the dispute without taking any claim to court.','The supplier settled the dispute privately instead of filing a lawsuit.','没有向法院提出主张而私下和解，并非 file a lawsuit。'),[Q('lawsuit',1,1,'A lawsuit is a legal claim started?','in court by one side against another','by using a washing machine','by praising a reviewer','lawsuit 指向法院提出的诉讼。'),Q('lawsuit',2,1,'Why did the supplier file suit?','attempts to settle unpaid invoices failed','the invoices had already been paid in full','the supplier wanted to mow the lawn','未付款争议无法解决，供应商提起诉讼。'),Q('lawsuit',3,1,'Which phrase is natural?','file a lawsuit against a company','file a lawsuit to praise a company','file a lawsuit on a lathe','file a lawsuit against 是自然搭配。'),Q('lawsuit',4,2,'Lawsuit can also refer to?','the dispute being decided by a court','a family member’s last name','a particular rule of nature','lawsuit 也可指法院正在审理的争端。')]);
P('lawyer','Lawyer is formed from law plus the agent/person suffix -yer and names someone qualified to advise about law or represent clients.',C('lawyer.s1','法律咨询','The lawyer explained the lease clause in plain language before the tenant signed the agreement.','租户签署协议前，律师用通俗语言解释了租约条款。','The lawyer explained the lease clause / in plain language / before the tenant signed / the agreement.','lawyer 作主语名词，指法律顾问；before 从句说明解释发生在签署前。','受过法律训练并为客户提供建议，符合 s1。'),M('The lawyer advised the tenant about the lease despite having no legal training or authorization to practice.','The tenant consulted a qualified lawyer about the lease.','没有法律训练且无执业资格者不能作为该义的 lawyer。'),[Q('lawyer',1,1,'A lawyer is a person trained to?','advise on law or represent clients','shape objects on a lathe','produce a beam of light','lawyer 指受训提供法律建议或代理客户的人。'),Q('lawyer',2,1,'What did the lawyer explain?','a clause in the lease','the north latitude of the house','the launderette opening hours','律师解释租约中的条款。'),Q('lawyer',3,1,'Which phrase is natural?','consult a lawyer about a contract','consult a lawyer to measure a larynx beam','a lawyer is a legal rule','consult a lawyer 是自然表达。'),Q('lawyer',4,2,'A lawyer may also be?','the attorney acting for one side in a case','the plaintiff’s family name','the judge’s lawn','律师也可指诉讼一方的代理律师。')]);
P('lax','Lax comes from Latin laxus, “loose”; it describes weak standards or a careless attitude toward rules and duties.',C('lax.s2','项目管理','The supervisor was lax about deadlines, so several reports arrived days after the agreed date.','主管对截止日期要求松懈，因此好几份报告比约定日期晚了几天才交。','The supervisor was lax about deadlines / so several reports arrived / days after / the agreed date.','lax 修饰 supervisor 的管理态度；about deadlines 指其不严格的方面。','对职责不够认真导致延误，符合 s2。'),M('The inspector’s lax security kept every entrance locked, checked every badge, and admitted nobody without authorization.','The inspector maintained strict security by checking each badge and controlling access.','层层核查并严格控制出入不是 lax security。'),[Q('lax',1,1,'Lax security is?','not strict in control or discipline','extremely careful and tightly controlled','a final point in a presentation','lax 指松懈、不严格。'),Q('lax',2,2,'Why was the supervisor lax about deadlines?','reports repeatedly arrived after the agreed dates','every report arrived early','the supervisor enforced every rule carefully','对截止日不严格造成报告迟交。'),Q('lax',3,2,'Which phrase is natural?','a lax attitude toward safety rules','a lax guard who checks every badge carefully','laxly legal agreement','lax 可描述管理或态度不严格。'),Q('lax',4,2,'Lax can also describe a person who is?','careless about duties or rules','praised for a noble goal','a person who answers an interview','lax 也可描述对职责疏忽的人。')]);
P('lay','Lay comes from Old English lecgan, “put or place”; other senses include setting a table, producing eggs, and describing a non-specialist or non-clergy person.',C('lay.s1','整理地图','Lay the map flat on the table so everyone can see the route before the meeting starts.','把地图平放在桌上，这样开会前每个人都能看清路线。','Lay the map flat / on the table / so everyone can see the route / before the meeting starts.','lay 是及物动词，宾语 map 表示被放置的物体；flat 描述放置状态。','把地图放下并平放符合 s1。'),M('Lay the map on the table by holding it upright in the air and never placing it down.','Place the map flat on the table.','一直举在空中而不放下与 lay down/place 相反。'),[Q('lay',1,1,'To lay a map on a table is to?','put it down in a flat position','lead a group through a building','make sounds of amusement','lay 的基本及物义是放置。'),Q('lay',2,3,'A hen lays when it?','produces an egg','moves laterally across a room','files a lawsuit','lay s3 指产卵。'),Q('lay',3,4,'“Explain it in lay terms” means explain it for?','people without specialist training','the last people in a list','the legal enforcement officers only','lay terms 指外行能懂的说法。'),Q('lay',4,5,'A lay member of a church is?','not part of the clergy','a priest who leads worship','a person whose surname is Lay','lay s5 指非神职人员。')]);

P('lay down','Lay down combines lay and down; it means put something down or formally establish a rule or principle.',C('lay down.s1','实验室规范','The director laid down clear rules for labeling samples and recording every change to the experiment.','主任制定了清晰的规则，要求给样本贴标签并记录实验中的每次改动。','The director laid down clear rules / for labeling samples / and recording every change / to the experiment.','laid down 是及物短语动词，表示正式制定规则；for 引出规则所管事项。','主任规定统一流程，符合 s1。'),M('The director laid down rules by refusing to establish any procedure and telling staff to improvise.','The director established clear rules for staff to follow.','拒绝制定规则不符合 lay down 的“规定、确立”义。'),[Q('lay down',1,1,'To lay down a rule is to?','formally establish it for people to follow','hide it beneath a lawn','praise the person who broke it','lay down 可表示制定规则。'),Q('lay down',2,1,'What rules did the director lay down?','label samples and record experiment changes','arrive after the experiment ends','turn the samples on a lathe','规定涉及样本标记和实验记录。'),Q('lay down',3,1,'Which phrase is natural?','lay down safety requirements','lay down a rule by refusing to state it','lay down means “arrive late”','lay down 常与 rules/requirements 搭配。'),Q('lay down',4,1,'Lay down can also mean?','put something down','launch a product publicly','measure latitude','短语也保留 lay 的“放下”义。')]);
P('lay out','Lay out combines lay and out and means arrange something in a clear, planned way.',C('lay out.s1','版面规划','The designer laid out the exhibition panels so visitors could follow the story from the entrance to the final room.','设计师规划了展板布局，让访客能够从入口一路按顺序读到最后一个展厅。','The designer laid out the exhibition panels / so visitors could follow the story / from the entrance / to the final room.','laid out 表示规划安排；so 引出布局所实现的参观效果。','展板按路线有条理地安排，符合 s1。'),M('The designer laid out the panels by stacking them randomly in a locked storage room where visitors could not see them.','The designer arranged the panels along the visitor route.','随机堆在储藏室里不算为展示而规划布局。'),[Q('lay out',1,1,'To lay out a page or room is to?','arrange its parts in a clear plan','confine someone without trial','move in a direction to the side','lay out 指有计划地安排。'),Q('lay out',2,1,'Why were the panels laid out in sequence?','so visitors could follow the story through the rooms','so visitors would never find the entrance','to create a lawsuit','有序布局引导观众按故事路线参观。'),Q('lay out',3,1,'Which phrase is natural?','lay out the page for printing','lay out the page without arranging anything','lay out a person to mean “surname”','lay out 可表示排版或规划。'),Q('lay out',4,1,'The noun layout is related to?','the planned arrangement of parts','the act of praising someone','a short triangular sail','layout 名词指布局。')]);
P('layer','Layer comes from lay plus -er and names a sheet or level; as a verb it means to arrange things in layers.',C('layer.s1','室内清洁','A thin layer of dust had settled on the shelf during the weeks when the office was closed.','办公室关闭的几周里，架子上积了一层薄灰。','A thin layer of dust / had settled / on the shelf / during the weeks when the office was closed.','layer 作可数名词，指覆盖表面的薄层；of dust 说明材料。','灰覆盖成一层，符合 s1。'),M('A layer of dust covered the shelf although no dust or other substance was present on it.','A clean shelf had no dust layer on it.','没有任何灰尘或材料时不存在 dust layer。'),[Q('layer',1,1,'A layer of dust is?','a sheet-like amount covering a surface','a person who leads a group','a legal claim','layer 可指覆盖表面的一层物质。'),Q('layer',2,2,'In a company, a layer of management can mean?','one level in its organization','a thin coat of dust','an egg laid by a hen','layer 也可指系统中的层级。'),Q('layer',3,3,'To layer potatoes and sauce is to?','arrange them in successive levels','place them randomly in one pile','file a lawsuit about them','动词 layer 指分层摆放。'),Q('layer',4,1,'Which phrase is natural?','a layer of paint on the wall','a layer of law that means “a rule”','layer the shelf with a surname','a layer of paint 是自然搭配。')]);
P('layman','Layman is formed from lay, “not belonging to the clergy or a specialist profession,” plus man; it can mean a non-specialist or a non-clergy church member.',C('layman.s1','科普讲座','The engineer explained the battery design in terms a layman could understand, avoiding technical abbreviations.','工程师用外行也能理解的说法解释电池设计，避免使用专业缩写。','The engineer explained the battery design / in terms a layman could understand / avoiding / technical abbreviations.','layman 作 terms 的受众，指没有该领域专门知识的人；could understand 限定表达难度。','说明面向非专业听众，符合 s1。'),M('The engineer wrote for a layman by using unexplained specialist jargon that only experienced engineers could follow.','The engineer wrote for non-specialists using clear, accessible language.','只有专家能懂的术语不适合 layman 受众。'),[Q('layman',1,1,'A layman in a technical discussion is?','someone without specialist knowledge of the subject','a person who leads a religious service','a person honored with a prize','layman 可指非专业人士。'),Q('layman',2,1,'Why did the engineer avoid abbreviations?','the explanation was for a layman','the audience consisted only of senior specialists','the battery was on a lawn','面向外行时应避免未解释的术语。'),Q('layman',3,1,'Which phrase is natural?','explain the result in layman’s terms','layman’s terms only for the expert who designed it','layman a technical report carefully','layman’s terms 指通俗易懂的表达。'),Q('layman',4,2,'In a church, a layman may be?','a member who is not a priest','the priest leading the service','a court official filing a claim','宗教语境中 layman 可指平信徒。')]);
P('layoff','Layoff is the noun formed from lay off; it can mean ending a worker’s employment because fewer workers are needed or a temporary period without work.',C('layoff.s1','工厂经营','The factory announced a layoff after orders fell, giving affected workers several weeks of notice.','订单减少后，工厂宣布裁员，并提前数周通知受影响员工。','The factory announced a layoff / after orders fell / giving affected workers / several weeks of notice.','layoff 指因雇主不再需要那么多员工而停止雇用；after 引出经济原因。','员工因订单减少被裁，符合 s1。'),M('The company called it a layoff even though every worker kept the same job and no one lost employment or work.','The company kept all staff employed and did not carry out a layoff.','没人失业或停工就没有发生裁员。'),[Q('layoff',1,1,'A layoff can be?','an employer ending a worker’s employment because fewer workers are needed','a prize awarded to a poet','a formal legal rule','layoff 可指裁员。'),Q('layoff',2,1,'Why did the factory announce layoffs?','orders fell and fewer workers were needed','orders doubled and more staff were hired','the employees planted a lawn','订单减少导致企业裁员。'),Q('layoff',3,1,'Which phrase is natural?','mass layoffs at the factory','a layoff that means all staff were promoted','a layoff the company lauded','mass layoffs 是常见搭配。'),Q('layoff',4,2,'Layoff can also describe?','a period when workers are temporarily told not to work','a long-term layer of soil','the last person in a sequence','layoff 也可指暂时停工期。')]);
P('layout','Layout is formed from lay out and means the arrangement of rooms, objects, or text and images on a page.',C('layout.s2','出版校对','The editor adjusted the page layout so the chart and its caption appeared together instead of on separate pages.','编辑调整了页面版式，让图表和说明文字放在一起，而不是分散到两页。','The editor adjusted the page layout / so the chart and its caption appeared together / instead of / on separate pages.','layout 指页面上文字和图片的安排；so 引出排版调整的目的。','编辑调整图文在页面上的位置，符合 s2。'),M('The page layout separated the chart from its caption by placing them together in the same position.','The editor changed the layout to keep the chart and caption together.','把图表与说明放在一起并非分开二者。'),[Q('layout',1,2,'Page layout is?','the way text and pictures are arranged on a page','a rule passed by Parliament','the act of praising a person','layout 可指页面版式。'),Q('layout',2,2,'Why did the editor adjust the layout?','to keep the chart and caption together','to hide the chart from every reader','to change the writer’s family name','版式调整让图表与说明同页。'),Q('layout',3,1,'A room layout describes?','how rooms or objects are arranged in space','a period when a factory has no orders','a person’s legal training','layout 也可描述空间安排。'),Q('layout',4,2,'Which phrase is natural?','a two-column page layout','a page layout with text placed nowhere','layout the floor means “praise”','two-column page layout 是自然搭配。')]);
P('lazily','Lazily is formed from lazy plus -ly and means without energy or hurry, or in a relaxed unhurried manner.',C('lazily.s1','周末早晨','On Sunday, the cat stretched lazily in the sun and did not move until someone opened the food cupboard.','周日，猫懒洋洋地在阳光下伸展，直到有人打开食品柜才动身。','On Sunday / the cat stretched lazily in the sun / and did not move / until someone opened the food cupboard.','lazily 修饰 stretched，表示动作懒散不急；until 标出它开始活动的时间。','猫缓慢松弛地伸展，符合 s1。'),M('The cat stretched lazily by sprinting at full speed across the room and working without pause.','The cat stretched slowly and relaxed in the sun.','全速奔跑、不停活动与 lazily 的松弛状态相反。'),[Q('lazily',1,1,'To move lazily is to move?','without energy or hurry','with urgent speed and intense effort','in a direction north of the equator','lazily 表示懒散地或不慌不忙地。'),Q('lazily',2,1,'How did the cat stretch?','slowly and in a relaxed way','at full speed without stopping','while operating a lathe','猫在阳光下松弛地伸展。'),Q('lazily',3,1,'Which sentence uses lazily naturally?','He lazily turned a page and returned to the sofa.','He lazily sprinted at top speed for hours.','He lazy read the page yesterdayly.','lazily 可修饰慢悠悠翻页的动作。'),Q('lazily',4,1,'The adjective related to lazily is?','lazy','lawful','lateral','lazily 由 lazy 派生。')]);
P('lazuli','Lazuli is a shortened form of lapis lazuli; the name passed through Medieval Latin from Arabic lazuward, “azure stone.”',C('lazuli.s1','珠宝工艺','The pendant was inlaid with lazuli, whose deep blue color contrasted with the pale silver setting.','这枚吊坠镶嵌着青金石，其深蓝色与浅色银托形成对比。','The pendant was inlaid with lazuli / whose deep blue color / contrasted with / the pale silver setting.','lazuli 作不可数名词，指青金石；whose 指石头的颜色。','深蓝色宝石镶嵌在首饰上，符合 s1。'),M('The jeweler called the stone lazuli although it was a colorless sheet of paper with no mineral in it.','The jeweler identified the deep-blue stone as lazuli.','无矿物的纸张不是青金石。'),[Q('lazuli',1,1,'Lazuli is a shortened name for?','lapis lazuli, a deep-blue stone','a legal instrument for filing claims','a machine that turns wood','lazuli 是 lapis lazuli 的简称。'),Q('lazuli',2,1,'What feature stood out on the pendant?','the stone’s deep blue color','a green lawn growing inside it','a laser that emitted sound','青金石的深蓝色与银托形成对比。'),Q('lazuli',3,1,'Which phrase is natural?','a lazuli inlay in a pendant','a lazuli family name','a lathe of blue liquid','lazuli 可指镶嵌的蓝色宝石。'),Q('lazuli',4,1,'The name is historically linked to Arabic?','lazuward, “azure stone”','law, “a country rule”','laughter, “sound of amusement”','词源经阿拉伯语 lazuward 传来。')]);
P('lazy','Lazy is an adjective for unwillingness to work or be active, careless effort, or slow relaxed movement.',C('lazy.s2','学习反馈','The teacher returned the essay because its lazy argument repeated the textbook without checking any evidence.','老师退回了这篇文章，因为其中敷衍的论证只是重复教材，完全没有核查证据。','The teacher returned the essay / because its lazy argument / repeated the textbook / without checking any evidence.','lazy 修饰 argument，表示不认真、缺少投入；because 解释退回原因。','论证缺乏核查和努力，符合 s2。'),M('The student’s argument was lazy because it carefully tested several sources and explained every conclusion.','The student’s argument was thorough because it tested several sources and supported its conclusions.','认真核查多份来源不属于敷衍论证。'),[Q('lazy',1,1,'A lazy person may be?','unwilling to work or be active','extremely eager to take on every task','a person honored with a title','lazy 可指不愿工作或活动的。'),Q('lazy',2,2,'A lazy piece of work shows?','little care or effort','careful checking of every source','a formal prize','缺少证据核查体现敷衍。'),Q('lazy',3,3,'A “lazy river” describes water that?','moves slowly and calmly','is unwilling to work','has many laws','lazy 也可形容缓慢流动的河水。'),Q('lazy',4,1,'Which phrase is natural?','too lazy to cook','lazy to cooked dinner yesterday','a lazily argument','too lazy to 是常见结构。')]);
P('lea','Lea comes from Old English leah, “open field or meadow,” related to a grassy clearing.',C('lea.s1','乡村景象','At dusk, the sheep gathered on the lea beside the stream before the shepherd led them home.','黄昏时，羊群聚集在溪边的草地上，之后牧羊人把它们赶回家。','At dusk / the sheep gathered on the lea / beside the stream / before the shepherd led them home.','lea 作介词 on 的宾语，指供动物吃草的草地；before 表示回家前的活动。','羊群在草地上觅食，符合 s1。'),M('The sheep grazed on the lea, a deep ocean trench far below the surface.','The sheep grazed on the lea, an open grassy meadow.','海底海沟不是草地或牧场。'),[Q('lea',1,1,'A lea is?','grassland where animals may feed','a room with a toilet','a narrow beam of light','lea 指草地、牧场。'),Q('lea',2,1,'Where did the sheep gather?','on a grassy field beside the stream','inside a law court','on a lateen sail','羊群聚集在溪边草地。'),Q('lea',3,1,'Which phrase is natural?','sheep grazing on the lea','sheep grazing on a metal lathe','a lea of laughter','lea 是较旧或诗歌式的草地名词。'),Q('lea',4,1,'The Old English source leah referred to?','an open field or meadow','a laser acronym','a young woman','词源 leah 指开阔地或草地。')]);

P('leach','Leach is historically connected with Old English leccan, “moisten or irrigate,” and related Germanic verbs for water seeping through material.',C('leach.s1','土壤保护','Heavy rain can leach nutrients from sandy soil, so growers add compost before planting another crop.','大雨会把养分从沙土中冲走，因此种植者会在种下一茬作物前添加堆肥。','Heavy rain can leach nutrients / from sandy soil / so growers add compost / before planting another crop.','leach 作及物动词，表示水把化学物质从固体中洗出；from 引出被冲洗的土壤。','雨水使养分从土壤流失，符合 s1。'),M('Rain leached nutrients from the soil even though no water passed through or washed anything away.','Rain dissolved and carried nutrients out of the soil.','没有水流经材料，就不会发生 leaching。'),[Q('leach',1,1,'To leach a chemical from soil is to?','wash it out with water','bind it to a surface with rope','praise the soil formally','leach 指用水冲洗出化学物质。'),Q('leach',2,1,'Why might growers add compost after heavy rain?','rain may have leached nutrients from the sandy soil','rain permanently increased every nutrient','compost measures the soil’s latitude','大雨会冲走土壤养分。'),Q('leach',3,1,'Which phrase is natural?','chemicals leach from the soil','chemicals leach into a lawsuit','a leach is a person’s last name','leach 可描述化学物质从土壤中流失。'),Q('leach',4,2,'Leach can also be used as a noun for?','a substance removed by leaching or the process','a legal advocate','a grassy meadow','名词 leach 指滤出物或浸出过程。')]);
P('lead','Lead the guiding verb comes from Old English lædan, “show the way”; the metal noun lead is a separate Old English word of uncertain origin.',C('lead.s3','道路指引','The narrow path leads hikers to a spring that remains cool even during the dry season.','这条狭窄小路通向一处泉水，即使旱季也保持清凉。','The narrow path leads hikers / to a spring / that remains cool / even during the dry season.','leads to 表示通向；that 从句补充泉水的特点。','小路引导人到达某处，符合动词 s3 的去向义。'),M('The path leads to the spring by ending far away from it and pointing in the opposite direction.','The path leads to the spring by reaching it.','路线若远离泉水且朝反方向，并没有通向泉水。'),[Q('lead',1,3,'A path can lead to a place by?','going toward or reaching it','being made of the metal lead','arriving after the path ends elsewhere','lead 可表示通向某地。'),Q('lead',2,1,'In “She led the way,” lead means?','go in front and show the route','give away secret information','make a workpiece rotate','lead s1 指带路。'),Q('lead',3,4,'In “The team took the lead,” lead is a?','noun meaning the position ahead','verb meaning to wash soil','noun meaning a court suit','take the lead 表示领先。'),Q('lead',4,6,'Lead pipes are made of?','the heavy soft grey metal Pb','the act of showing a route','the last point in a list','lead 作金属名词时读音与动词不同。')]);
P('lead into','Lead into is a phrasal verb meaning to go from one topic or space into the next.',C('lead into.s1','演讲结构','The speaker’s brief story leads into the main argument about public access to the river.','演讲者先讲的简短故事自然引出关于公众河岸通行权的主要论点。','The speaker’s brief story / leads into the main argument / about public access / to the river.','lead into 后接进入的下一话题；故事在结构上过渡到论点。','开场故事引入主要论点，符合 s1。'),M('The introduction leads into the main topic by ending the talk and preventing anyone from reaching it.','The introduction leads into the main topic by preparing listeners for it.','完全终止讨论而阻止进入主题并非 lead into。'),[Q('lead into',1,1,'An introduction that leads into a topic?','moves naturally from one part to the next','causes a leak in a pipe','measures latitude','lead into 表示过渡到下一个部分。'),Q('lead into',2,1,'What does the short story lead into?','the main argument about river access','a launderette across town','a family name on a form','故事引出关于河岸通行的论点。'),Q('lead into',3,1,'Which sentence is natural?','The opening example leads into the discussion.','The opening example leads into by yesterday.','The discussion is leaded into the floor.','lead into 后可接新主题。'),Q('lead into',4,1,'Lead into often describes a transition between?','one subject or place and the next','two metal elements in a pipe','a law and its lawyer','该短语强调从一部分过渡到下一部分。')]);
P('lead to','Lead to means to cause a result or to go toward a place.',C('lead to.s1','事故调查','A loose cable led to the shutdown of the instrument, so the lab replaced it before restarting the test.','电缆松脱导致仪器关闭，因此实验室更换电缆后才重新开始测试。','A loose cable led to the shutdown / of the instrument / so the lab replaced it / before restarting the test.','lead to 表示导致结果；to 后接名词性短语 the shutdown。','电缆问题造成仪器停机，符合因果义。'),M('The loose cable led to the shutdown by having no effect on the instrument and causing nothing to happen.','The loose cable caused the instrument to shut down.','完全没有影响却说导致停机，因果关系矛盾。'),[Q('lead to',1,1,'A small error can lead to a failure when it?','causes that result','is a person’s surname','is the last item in a list','lead to 可表示导致结果。'),Q('lead to',2,1,'What led to the instrument shutdown?','a loose cable','a well-mowed lawn','a Latin language lesson','电缆松脱导致仪器关闭。'),Q('lead to',3,1,'Which phrase is grammatical?','Poor drainage can lead to flooding.','Poor drainage can lead flooding to.','Poor drainage leads into flooding to.','lead to 后接导致的结果。'),Q('lead to',4,1,'Lead to can also mean a path?','goes toward a place','goes only to an earlier time','is a legal representative','该短语也可表示通向某地。')]);
P('leader','Leader is formed from lead plus -er and names a person who leads a group, country, or organization.',C('leader.s1','志愿团队','The team chose a leader who listened to each volunteer before assigning roles for the cleanup.','团队选出一位领导者，在为清洁行动分配任务前先听取每位志愿者的意见。','The team chose a leader / who listened to each volunteer / before assigning roles / for the cleanup.','leader 作 chose 的宾语，指带领团队的人；who 从句说明其领导方式。','该人组织团队并分配任务，符合 s1。'),M('The group chose a leader who refused to guide anyone, organize the work, or make any decisions.','The group chose a leader who organized the cleanup and guided the volunteers.','拒绝带领和组织的人没有履行 leader 的职能。'),[Q('leader',1,1,'A leader is someone who?','leads a group or organization','is a sheet of paper in a book','causes water to leak','leader 指团队或组织的带领者。'),Q('leader',2,1,'What did the chosen leader do?','listened to volunteers and assigned roles','left everyone without direction','launched a metal lathe','她听取成员意见并安排工作。'),Q('leader',3,1,'Which phrase is natural?','the leader of the research team','the leader is the same as every team member in all contexts','leadership the leader yesterday','leader 常与 of 连用指出所领导的群体。'),Q('leader',4,1,'Leader is derived from which verb?','lead','leach','leak','leader 由 lead 加 -er 构成。')]);
P('leadership','Leadership is formed from leader plus -ship and means the leaders of an organization or the ability to lead.',C('leadership.s1','社区治理','The new director showed steady leadership by explaining the budget and inviting residents to question each decision.','新主任通过解释预算并邀请居民质疑每项决定，展现了稳健的领导能力。','The new director showed steady leadership / by explaining the budget / and inviting residents / to question each decision.','leadership 作 showed 的宾语，指领导能力；by 引出展示能力的做法。','沟通透明并组织讨论体现有效领导，符合 s1。'),M('The director demonstrated leadership by hiding the budget, silencing residents, and refusing to make decisions.','The director demonstrated poor leadership by hiding information and silencing residents.','隐瞒信息和压制意见并非题句所称的稳健领导力。'),[Q('leadership',1,1,'Leadership can mean?','the ability to guide an organization or its leaders','the grass in a park','a person’s late arrival','leadership 可指领导能力或领导层。'),Q('leadership',2,1,'How did the director show leadership?','explained the budget and invited questions','hid all decisions from residents','refused to discuss the budget','公开解释并接受质疑展现领导能力。'),Q('leadership',3,1,'Which phrase is natural?','strong leadership during a crisis','leadership is a machine for launching rockets','leaderships one person into a room','strong leadership 是自然搭配。'),Q('leadership',4,1,'Leadership is formed from leader plus?','-ship','-ie','-al','-ship 可构成表示身份或能力的名词。')]);
P('leading','Leading is the -ing form of lead used as an adjective meaning most important or in first position.',C('leading.s1','科研团队介绍','A leading researcher in the field presented the new findings at the international conference.','该领域的一位顶尖研究员在国际会议上发布了新发现。','A leading researcher in the field / presented the new findings / at the international conference.','leading 前置修饰 researcher，表示处于领先或重要地位；in the field 限定领域。','研究员在领域内处于重要地位，符合 s1。'),M('The journal called a leading study unimportant and last in its field, despite it being the first and most influential.','The journal described the study as leading because it was important and influential.','把研究说成无关紧要与 leading 的“领先/重要”义矛盾。'),[Q('leading',1,1,'A leading researcher is?','one of the most important or prominent researchers','someone arriving after the expected time','a person with no role in research','leading 可指重要或领先的。'),Q('leading',2,1,'Why was the study called leading?','it was influential in its field','it was the least important study','it contained only a family surname','leading study 意味着重要且有影响力。'),Q('leading',3,1,'Which phrase is natural?','a leading role in the project','a leading role at the end of every list only','a leading, meaning “slowly”','leading 可修饰 role，表示重要的角色。'),Q('leading',4,1,'Leading can also describe someone?','in first position','who is confined without trial','who lives on a grassy lea','leading 也可表示位居第一。')]);
P('leaf','Leaf comes from Old English leaf, from a Germanic word for foliage; it names a plant part, a sheet in a book, thin metal, or the verb “turn pages.”',C('leaf.s1','秋季观察','Each leaf on the maple turned red before dropping onto the path.','枫树上的每片叶子都在落到小路上之前变红了。','Each leaf on the maple / turned red / before dropping / onto the path.','leaf 作可数名词，指植物的叶片；before 表示变色先于掉落。','树叶变红后落下，符合植物义 s1。'),M('Each leaf on the maple turned red before dropping from the printed book onto the path.','Each leaf on the maple tree turned red before falling to the ground.','树木的叶子不会从印刷书页上掉下来。'),[Q('leaf',1,1,'A leaf on a tree is?','one of the flat parts that grows from a plant','the family name shared by relatives','a legal claim in court','leaf s1 指植物叶片。'),Q('leaf',2,2,'A leaf in a book can mean?','a sheet of paper with a page on each side','a plant’s green part only','a machine that cuts wood','leaf 也可指书中的一张纸。'),Q('leaf',3,3,'Gold leaf is?','a very thin sheet of metal','a leaf from a golden tree only','a legal rule about gold','leaf s3 可指薄金属片。'),Q('leaf',4,4,'To leaf through a magazine is to?','turn its pages quickly','grow new foliage','file a lawsuit','leaf 作动词可表示快速翻阅。')]);
P('leafcutter','Leafcutter is a compound of leaf and cutter, commonly naming a tropical ant that cuts leaves to grow fungus for food.',C('leafcutter.s1','热带雨林观察','A line of leafcutters carried green fragments back to the nest, where the colony used them to cultivate fungus.','一队切叶蚁把绿色叶片碎块搬回巢穴，蚁群在那里用它们培育真菌。','A line of leafcutters carried green fragments / back to the nest / where the colony used them / to cultivate fungus.','leafcutter 作复数名词，指切叶蚁；where 指巢穴，to cultivate 表示叶片用途。','切叶蚁用植物碎片培育真菌，符合 s1。'),M('The leafcutters carried leaves to the nest to eat the leaves as their only food, never cultivating fungus.','The leafcutters use cut leaves as a base for cultivating fungus.','此类蚂蚁主要用叶片培育真菌，而不是把叶片当唯一食物。'),[Q('leafcutter',1,1,'A leafcutter ant uses leaf pieces mainly to?','cultivate the fungus it farms','make a metal lathe','write a law','切叶蚁把叶片用作培育真菌的基质。'),Q('leafcutter',2,1,'Where did the leafcutters take the fragments?','back to their nest','to a law court','into the larynx','蚂蚁把叶片运回巢穴。'),Q('leafcutter',3,1,'Which phrase is natural?','leafcutter ants in a tropical forest','leafcutter ants that never cut or carry leaves','leafcutter a lawsuit quickly','leafcutter 常见于 leafcutter ant。'),Q('leafcutter',4,1,'The word combines leaf with?','cutter','laureate','latitude','leafcutter 由 leaf 和 cutter 组成。')]);
P('leaflet','Leaflet combines leaf with -let and can mean a small information sheet or one small division of a compound leaf.',C('leaflet.s1','社区宣传','Volunteers handed out a leaflet explaining where residents could obtain free flu vaccinations.','志愿者分发了一份传单，说明居民可以在哪里免费接种流感疫苗。','Volunteers handed out a leaflet / explaining where residents could obtain / free flu vaccinations.','leaflet 作 hand out 的宾语，指印刷信息单；explaining 分词短语说明内容。','一张印刷纸介绍公共服务，符合 s1。'),M('The leaflet explained vaccination sites even though it was a blank sheet with no text or printed information.','The leaflet contained printed information about vaccination sites.','没有任何文字的空白纸无法解释接种地点。'),[Q('leaflet',1,1,'An information leaflet is?','a printed sheet or small booklet giving information','a large court building','a device for shaping wood','leaflet 可指传单或小册子。'),Q('leaflet',2,1,'What did the volunteers hand out?','information about free vaccination sites','a medal to every lawyer','a thin layer of dust','传单解释接种地点。'),Q('leaflet',3,1,'Which phrase is natural?','hand out leaflets at the clinic','hand out leaflets with no text or information','leaflet a person into court','hand out leaflets 是常见搭配。'),Q('leaflet',4,2,'In botany, a leaflet can also be?','one small division of a compound leaf','the whole tree trunk','a legal claim','植物学中 leaflet 是复叶的一个小叶片。')]);
P('leafstalk','Leafstalk is the compound leaf plus stalk and names the narrow part attaching a leaf blade to the stem.',C('leafstalk.s1','植物结构','The leafstalk bent under the weight of the raindrops but remained attached to the stem.','叶柄在雨滴的重量下弯曲，但仍连在茎上。','The leafstalk bent / under the weight of the raindrops / but remained attached / to the stem.','leafstalk 作主语名词，指连接叶片和茎的细长部分；but 表示弯曲却未脱落。','叶柄弯曲并连接叶片与茎，符合 s1。'),M('The leafstalk is the broad flat blade of a leaf, not the narrow part connecting it to the stem.','The leafstalk is the narrow attachment between the leaf blade and stem.','宽阔的叶片部分不是 leafstalk。'),[Q('leafstalk',1,1,'A leafstalk attaches the leaf blade to the?','stem','courtroom','equator','leafstalk 是连接叶片和茎的部分。'),Q('leafstalk',2,1,'What happened to the leafstalk in the example?','it bent but stayed attached','it became a printed leaflet','it fell from the plant and became a law','雨滴压弯叶柄，但它没有折断。'),Q('leafstalk',3,1,'Which term is a technical synonym for leafstalk?','petiole','laurel','latter','petiole 是叶柄的专业术语。'),Q('leafstalk',4,1,'Leafstalk is formed from leaf plus?','stalk','ship','less','leafstalk 是复合词 leaf+stalk。')]);
P('leafy','Leafy is formed from leaf plus -y and means covered with leaves or having many trees and plants.',C('leafy.s1','城市规划','The city planted shade trees along the avenue, turning the once-bare blocks into a leafy neighborhood.','市政府沿大道种植遮阴树木，使原本光秃秃的街区变成了绿树成荫的社区。','The city planted shade trees / along the avenue / turning the once-bare blocks / into a leafy neighborhood.','leafy 修饰 neighborhood，表示树木和植物繁茂；turning 引出种植后的变化。','街区增添树木后变得绿意盎然，符合 s1。'),M('The neighborhood was leafy despite having no trees, plants, leaves, or green spaces anywhere in it.','The neighborhood became leafy after the city planted trees along its streets.','没有树叶或植被的地方不可能 leafy。'),[Q('leafy',1,1,'A leafy neighborhood has?','many trees or plants','many court cases','a machine in every room','leafy 表示树木或植物繁茂的。'),Q('leafy',2,1,'What made the blocks leafy?','the city planted shade trees','the city removed every tree','the blocks were measured in degrees','种植树木让街区绿树成荫。'),Q('leafy',3,1,'Which phrase is natural?','a leafy suburb with mature trees','a leafy street with no plants or leaves','leafy a tree quickly','leafy 可修饰郊区或街道。'),Q('leafy',4,1,'Leafy is formed from leaf plus?','-y','-ness','-ee','-y 可构成“多叶的、覆盖叶子的”形容词。')]);
P('league','League comes through French ligue and Italian lega from Latin ligare, “bind”; it can mean a sports association, a purpose-based alliance, or a level of quality.',C('league.s1','足球联赛','The club moved into the top league after winning promotion at the end of the season.','这个俱乐部在赛季末赢得升级资格后，进入了顶级联赛。','The club moved into the top league / after winning promotion / at the end / of the season.','league 指相互比赛的球队组织；after 引出升级到该联赛的时间。','俱乐部进入球队竞赛组织，符合 s1。'),M('The club joined a league by refusing every match and remaining outside all teams and competition.','The club joined the league and competed against its member teams.','拒绝所有比赛且不加入组织，不能称作加入联赛。'),[Q('league',1,1,'A sports league is?','a group of teams that compete with one another','a room where clothes are washed','a set of leaves on one plant','league 可指体育联赛。'),Q('league',2,1,'What happened to the club?','it was promoted to a higher league','it became a court case','it moved laterally off the field forever','俱乐部通过升级进入顶级联赛。'),Q('league',3,2,'A league may also be?','an alliance of people, clubs, or countries','a single person’s last name','a machine that produces laser light','league 也可指为共同目的组成的联盟。'),Q('league',4,3,'“Their food is not in the same league” compares?','quality or level','geographic latitude','a period of lateness','口语中 league 也可表示水平或档次。')]);
P('leak','Leak may derive from a Germanic verb for dripping or trickling; it means liquid or gas escapes, secrets are disclosed, or a hole lets them out.',C('leak.s1','屋顶检修','Water leaked through the roof during the storm, so the caretaker placed a bucket under the ceiling stain.','暴风雨期间雨水从屋顶漏进来，因此管理员在天花板水渍下放了一个桶。','Water leaked through the roof / during the storm / so the caretaker placed / a bucket under the ceiling stain.','leaked 是不及物动词，表示液体意外渗出；so 引出应对措施。','水从屋顶渗入，符合 s1。'),M('Water leaked through the roof even though the roof was sealed and not a drop entered or escaped.','Water leaked through an opening in the roof.','完全密封且没有水通过，不构成泄漏。'),[Q('leak',1,1,'If water leaks from a pipe, it?','escapes through a hole or crack','is praised by a reviewer','turns into a family name','leak 作动词可表示液体意外漏出。'),Q('leak',2,1,'What did the caretaker do after the roof leaked?','placed a bucket under the stain','launched the roof into space','filed every leaf in a book','管理员在漏水处放桶接水。'),Q('leak',3,2,'To leak secret information is to?','give it to the public without permission','keep it completely confidential','measure it north of the equator','leak 也可指泄露秘密信息。'),Q('leak',4,3,'As a noun, a leak can be?','a hole that lets liquid escape','a person who leads a group','the second of two choices','leak 名词可指使液体逸出的孔洞。')]);
P('leakage','Leakage is formed from leak plus -age and means escaping liquid, gas, or information, or the amount that escapes.',C('leakage.s1','校园安全','A gas leakage in the kitchen triggered the alarm and forced the school to close the building for inspection.','厨房发生煤气泄漏后，警报响起，学校不得不关闭大楼进行检查。','A gas leakage in the kitchen / triggered the alarm / and forced the school / to close the building for inspection.','leakage 作主语名词，指气体外泄事件；and 连接引发的两项后果。','煤气从管道或设备中逸出，符合 s1。'),M('The alarm responded to a gas leakage even though no gas escaped and no substance was present.','The alarm responded to gas that had escaped from the kitchen.','没有任何气体逸出就不存在 gas leakage。'),[Q('leakage',1,1,'Leakage can mean?','the escape of liquid, gas, or information','a carefully sealed system with no escape','the person who asks interview questions','leakage 指泄漏或泄密。'),Q('leakage',2,1,'What caused the school alarm?','gas escaped in the kitchen','a laurel tree grew in the yard','the league changed its name','厨房煤气泄漏触发警报。'),Q('leakage',3,1,'Which phrase is natural?','information leakage from a private server','leakage that means nothing escaped','a leakage of two teams in a league','information leakage 是自然搭配。'),Q('leakage',4,2,'Leakage can also refer to?','the amount of liquid or gas that escapes','the last point in a list','a triangular sail','该词还可指泄漏出来的量。')]);
P('leaky','Leaky is formed from leak plus -y and means having an opening that lets liquids or gases escape, or metaphorically revealing secrets.',C('leaky.s1','房屋维护','They replaced the leaky roof before autumn because rain had begun to drip into the attic.','秋天到来前，他们更换了漏水的屋顶，因为雨水已经开始滴进阁楼。','They replaced the leaky roof / before autumn / because rain had begun / to drip into the attic.','leaky 修饰 roof，表示屋顶有孔隙使雨水通过；because 解释维修原因。','雨水从屋顶漏入阁楼，符合 s1。'),M('They repaired the leaky roof even though it was perfectly sealed and never allowed water through.','They repaired the roof because water leaked through it.','完全密封、不漏水的屋顶不能称为 leaky。'),[Q('leaky',1,1,'A leaky roof?','has openings that let water through','is guaranteed to keep every drop out','is a person’s name','leaky 指有漏洞、会漏水的。'),Q('leaky',2,1,'Why was the roof replaced?','rain had begun dripping into the attic','the roof was perfectly sealed','the house was in a football league','雨水漏入阁楼，说明屋顶漏水。'),Q('leaky',3,2,'A “leaky cabinet” can metaphorically mean a cabinet that?','reveals secrets or private information','has no members or meetings','contains a lathe','leaky 可比喻容易泄露秘密。'),Q('leaky',4,1,'Leaky is formed from leak plus?','-y','-ship','-al','-y 构成形容词，表示容易发生 leak。')]);
P('lean','Lean as a verb comes from Old English hlinian, “bend or rest against”; the adjective lean can describe low-fat meat or an economy using few resources.',C('lean.s2','夜间阅读','Too tired to stand, Omar leaned against the wall while he listened to the final announcement.','奥马尔累得站不住，听最后一则广播时便靠在墙上。','Too tired to stand / Omar leaned against the wall / while he listened / to the final announcement.','leaned against 表示倚靠某物获得支撑；while 从句说明同时进行的动作。','身体靠墙支撑，符合动词 s2。'),M('Omar leaned against the wall by standing several feet away from it without touching or resting on it.','Omar rested his weight against the wall for support.','没有接触或倚靠不能使用 lean against。'),[Q('lean',1,2,'To lean against a wall is to?','rest against it for support','jump over it','praise it publicly','lean against 指倚靠。'),Q('lean',2,2,'What did Omar do because he was tired?','rested against the wall','jumped over the wall','turned the wall on a lathe','他靠墙支撑身体。'),Q('lean',3,3,'Lean meat contains?','little fat','a large amount of fat','a legal rule','lean 作形容词可指脂肪少的肉。'),Q('lean',4,4,'Lean times are periods when?','money or resources are limited','everyone has lavish spending','a lawn is full of trees','lean 也可形容资源紧张的时期。')]);
P('leap','Leap is an Old English verb and noun meaning a long or high jump; the verb also describes a sudden large increase.',C('leap.s1','动物行为','The young deer leaped over the fallen branch and continued toward the tree line.','小鹿跃过倒下的树枝，继续朝树林边缘跑去。','The young deer leaped / over the fallen branch / and continued / toward the tree line.','leaped 是不及物动词，over 引出跃过的障碍物。','小鹿跳过树枝，符合 s1。'),M('The deer leaped over the branch by walking underneath it without rising or jumping.','The deer jumped over the branch.','从树枝下方走过不是 leap over。'),[Q('leap',1,1,'To leap over an obstacle is to?','jump over it','walk underneath it','measure its latitude','leap 指跳跃或跃过。'),Q('leap',2,1,'What did the deer do?','jumped over a fallen branch','filed a lawsuit against the forest','grew leaves on the branch','小鹿跃过倒下的树枝。'),Q('leap',3,2,'Profits that leap to a record high?','increase suddenly by a large amount','remain unchanged','are formally praised','leap 也可表示数字猛增。'),Q('leap',4,3,'A leap can be a noun meaning?','a high or long jump','a legal advocate','a machine for washing clothes','leap 可作名词指跳跃。')]);
P('learn','Learn comes from Old English leornian; it can mean gain knowledge or a skill, discover a fact, or change behavior through experience.',C('learn.s3','安全复盘','After the near miss, the crew learned from the mistake and added a second check before each launch.','险些发生事故后，机组从错误中吸取教训，并在每次发射前增加了第二次检查。','After the near miss / the crew learned from the mistake / and added a second check / before each launch.','learn from 表示从经历中吸取经验；and 连接反思与改进措施。','机组改变流程以免重蹈覆辙，符合 s3。'),M('The crew learned from the mistake by repeating it deliberately and refusing to change any procedure.','The crew learned from the mistake by changing its checking procedure.','明知错误却重复且拒绝改进，未体现吸取教训。'),[Q('learn',1,1,'To learn a skill is to?','gain it through study or practice','file it in a court','make water escape through a hole','learn s1 指学习知识或技能。'),Q('learn',2,2,'In “I learned that the train was late,” learn means?','find out a fact or news','change the train’s physical length','lead the train into a courtroom','learn s2 可指得知消息。'),Q('learn',3,3,'What did the crew learn from its mistake?','to add another safety check','to repeat the same error','to stop recording launches','他们从险情中吸取教训并加强检查。'),Q('learn',4,1,'Which phrase is natural?','learn from experience','learn a mistake by ignoring it','learned is always pronounced as one syllable','learn from 表示从经验中学习。')]);
P('learned','Learned as an adjective comes from learn plus -ed and means having much knowledge from study; in this adjective it is pronounced with two syllables.',C('learned.s1','学术出版','The learned editor checked the footnotes carefully and recognized the classical sources cited in the manuscript.','这位学识渊博的编辑仔细核对脚注，并认出了手稿引用的古典文献。','The learned editor checked the footnotes carefully / and recognized / the classical sources / cited in the manuscript.','learned 修饰 editor，表示通过学习积累了丰富知识；cited 短语修饰 sources。','编辑凭深厚学识识别文献来源，符合 s1。'),M('The article called the editor learned because she had never studied the sources and knew nothing about them.','The article called the editor inexperienced because she did not know the sources.','毫无知识或学习经历与 learned 的形容词义矛盾。'),[Q('learned',1,1,'A learned scholar has?','a great deal of knowledge gained through study','no knowledge and no education','a leaky roof','learned 作形容词指博学的。'),Q('learned',2,1,'What showed the editor was learned?','she recognized classical sources in the notes','she could not read any citation','she replaced the manuscript with a lawn','编辑识别古典来源体现学识。'),Q('learned',3,1,'How many syllables does learned have in “a learned editor”?','two, pronounced /ˈlɜːnɪd/','one, pronounced exactly like the past tense /lɜːnd/','three, pronounced /ˈlɪːdɪd/','作形容词时 learned 读两个音节。'),Q('learned',4,1,'In “She learned the rule,” learned is?','the past tense of learn, pronounced /lɜːnd/','the two-syllable adjective meaning scholarly','a noun meaning a teacher','过去式 learned 与双音节形容词读音不同。')]);


})();
